// Straight-line distance in km between two points (haversine)
function distanceKm(a: { lat: number; lon: number }, b: { lat: number; lon: number }) {
  const rad = (d: number) => (d * Math.PI) / 180
  const h =
    Math.sin(rad(b.lat - a.lat) / 2) ** 2 +
    Math.cos(rad(a.lat)) * Math.cos(rad(b.lat)) * Math.sin(rad(b.lon - a.lon) / 2) ** 2
  return 2 * 6371 * Math.asin(Math.sqrt(h))
}
// One text for the order (the backend keeps a single delivery address)
const composeDeliveryAddress = (d: { calle: string; barrio: string; tipoEdificio: string; nombreEdificio: string; unidad: string }) =>
  [
    d.calle.trim(),
    d.barrio.trim() && `Barrio ${d.barrio.trim()}`,
    d.tipoEdificio && [d.tipoEdificio, d.nombreEdificio.trim()].filter(Boolean).join(" "),
    d.unidad.trim(),
  ]
    .filter(Boolean)
    .join(", ")

function addressPartsFromAddress(address: string) {
  const segments = address.split(",").map((part) => part.trim()).filter(Boolean)
  const barrio = neighborhoodNameFromAddress(address)
  const otherDetails = segments
    .slice(1)
    .filter((part) => !/^Barrio\s+/i.test(part))
    .join(", ")
  return {
    barrio,
    calle: segments[0] || "",
    tipoEdificio: "",
    nombreEdificio: "",
    unidad: otherDetails,
  }
}
// OpenStreetMap search (free). "#" breaks it ("Calle 50 #45-20" -> "Calle 50 45-20")
const neighborhoodFromGeocodedAddress = (address?: Record<string, string>) =>
  address
    ? [
        address.neighbourhood,
        address.suburb,
        address.city_district,
        address.quarter,
      ].find(Boolean)
    : undefined

const municipalityFromGeocodedAddress = (address?: Record<string, string>) =>
  address
    ? [address.city, address.town, address.village, address.municipality, address.county].find(Boolean)
    : undefined

async function geocodeAddress(queries: string[], signal: AbortSignal) {
  for (const q of queries.filter(Boolean)) {
    const url =
      "https://nominatim.openstreetmap.org/search?format=json&addressdetails=1&limit=1&countrycodes=co&bounded=1&viewbox=-75.75,6.55,-75.35,6.10&q=" +
      encodeURIComponent(`${q.replace(/#|No\.|N°/gi, " ").replace(/\s+/g, " ").trim()}, Bello, Antioquia, Colombia`)
    const res = await fetch(url, { signal, headers: { "Accept-Language": "es" } })
    if (!res.ok) throw new Error(`Mapa no disponible (${res.status})`)
    const [hit] = (await res.json()) as {
      lat: string
      lon: string
      address?: Record<string, string>
    }[]
    if (hit) {
      const reverseUrl =
        "https://nominatim.openstreetmap.org/reverse?format=jsonv2&addressdetails=1&zoom=18&lat=" +
        encodeURIComponent(hit.lat) +
        "&lon=" +
        encodeURIComponent(hit.lon)
      const reverseResponse = await fetch(reverseUrl, {
        signal,
        headers: { "Accept-Language": "es" },
      })
      if (!reverseResponse.ok) throw new Error(`Mapa no disponible (${reverseResponse.status})`)
      const reverse = (await reverseResponse.json()) as {
        address?: Record<string, string>
      }
      const neighborhood = neighborhoodFromGeocodedAddress(reverse.address)
        || neighborhoodFromGeocodedAddress(hit.address)
      const municipality = municipalityFromGeocodedAddress(reverse.address)
        || municipalityFromGeocodedAddress(hit.address)
      return { lat: Number(hit.lat), lon: Number(hit.lon), neighborhood, municipality }
    }
  }
  return null
}

const formatDuration = (minutes: number) => {
  const hours = Math.floor(minutes / 60)
  const remainingMinutes = minutes % 60
  if (!hours) return `${minutes} min`
  return remainingMinutes ? `${hours} h ${remainingMinutes} min` : `${hours} h`
}

// A long address shown one part per line ("Calle 50 # 45-20" / "Barrio Santa Ana" / "Torre 2 apto 301")
const AddressLines = ({ address }: { address: string }) => (
  <>
    {address.split(/,\s*/).filter(Boolean).map((part, i) => (
      <span key={i} className="block">{part}</span>
    ))}
  </>
)

// Adds an item to the cart; if the same product with the same sauces and additions is
// already there, only its quantity goes up
function addCartItem(items: CartItem[], item: CartItem): CartItem[] {
  const key = (i: CartItem) =>
    JSON.stringify([
      i.name,
      [...(i.sauces ?? [])].sort(),
      [...(i.additions ?? [])].map((a) => `${a.name}x${a.qty}`).sort(),
    ])
  const same = items.find((i) => key(i) === key(item))
  return same ? items.map((i) => (i === same ? { ...i, qty: i.qty + item.qty } : i)) : [...items, item]
}

