// ── Theme tokens ───────────────────────────────────────────────────────────────
function tk(dark: boolean) {
  return {
    bg: dark ? "#0D0F14" : "#F0EDE6",
    sidebarBg: dark ? "#111318" : "#FFFFFF",
    sidebarBd: dark ? "rgba(255,255,255,0.06)" : "rgba(0,0,0,0.08)",
    sidebarTx: dark ? "rgba(255,255,255,0.92)" : "rgba(30,25,18,0.85)",
    sidebarMu: dark ? "rgba(255,255,255,0.55)" : "rgba(30,25,18,0.45)",
    hdrBg: dark ? "#111318" : "#FFFFFF",
    hdrBd: dark ? "rgba(255,255,255,0.06)" : "rgba(0,0,0,0.08)",
    card: dark ? "#181B22" : "#FFFFFF",
    cardAlt: dark ? "#1E2128" : "#F8F5EF",
    border: dark ? "rgba(255,255,255,0.07)" : "rgba(0,0,0,0.08)",
    text: dark ? "#EAE4D8" : "#18160F",
    muted: dark ? "rgba(234,228,216,0.50)" : "rgba(24,22,15,0.48)",
    subtle: dark ? "rgba(234,228,216,0.22)" : "rgba(24,22,15,0.22)",
    input: dark ? "rgba(255,255,255,0.06)" : "rgba(0,0,0,0.04)",
    inputB: dark ? "rgba(255,255,255,0.12)" : "rgba(0,0,0,0.10)",
    hover: dark ? "rgba(255,255,255,0.04)" : "rgba(0,0,0,0.03)",
  }
}

function badgeSt(val: string | number) {
  const s = String(val)
  if (
    [
      "Activo",
      "Activa",
      "OK",
      "Recibida",
      "Completada",
      "Terminado",
      "Vigente",
      "Lista",
      "Entregado",
      "Entregada",
      "Resuelta",
      "Resuelto",
      "Devuelta a compra",
    ].includes(s)
  )
    return { bg: "rgba(58,109,94,0.14)", color: "#2E7D60" }
  if (
    [
      "Pendiente",
      "Por confirmar",
      "Recibido",
      "En producción",
      "Iniciada",
      "En gestión",
      "En camino",
      "Borrador",
      "Confirmado",
      "Normal",
      "Listo",
      "Devuelta en parte",
    ].includes(s)
  )
    return { bg: "rgba(182,140,28,0.14)", color: "#9A7010" }
  if (
    [
      "Bajo",
      "Alta",
      "Pend. Aprobación",
      "Producto no conforme",
      "Pendiente admin",
      "Cancelada",
      "Cancelado",
      "Agotado",
      "Obsoleta",
      "Inactivo",
      "Inactiva",
      "Anulada",
      "Anulado",
      "Registrada",
    ].includes(s)
  )
    return { bg: "rgba(165,65,49,0.14)", color: C.red }
  return null
}

// Quantities typed as "0,5" or "0.5" (a number input drops the comma in some browsers); NaN if not a number
const toDecimal = (value: string | number | undefined) => {
  const text = String(value ?? "").trim().replace(",", ".")
  return /^\d*\.?\d+$|^\d+\.$/.test(text) ? Number(text) : NaN
}

// How each stock movement origin (movimientos_stock.origen) reads in the insumo's history
const STOCK_ORIGIN: Record<string, string> = {
  SALDO_INICIAL: "Saldo inicial",
  COMPRA: "Compra",
  EDICION_COMPRA: "Compra editada",
  ANULACION_COMPRA: "Compra anulada",
  REACTIVACION_COMPRA: "Compra reactivada",
  PERDIDA: "Pérdida",
  EDICION_PERDIDA: "Pérdida editada",
  DEVOLUCION_PERDIDA: "Devuelto a la compra",
  PRODUCCION: "Producción",
  AJUSTE: "Ajuste manual",
}

// Purchases and losses can't be dated before the shop opened ("Desde 2013 en Bello")
const FIRST_DAY = "2013-01-01"

// Highest unit cost / price accepted (the database keeps 10 digits before the decimals)
const MAX_PRICE = 999_999_999

function fmt(n: number) {
  return `$${n.toLocaleString("es-CO")}`
}

// Document numbers compared without dots, dashes, spaces or case ("1.012.345" === "1012345")
function normalizeDocument(value: string | number | undefined) {
  return String(value ?? "").replace(/[^0-9a-z]/gi, "").toLowerCase()
}

// Compare names ignoring case, accents and extra spaces ("Cárnes " === "carnes")
function normalizeName(value: string | number | undefined) {
  return String(value ?? "")
    .normalize("NFD")
    .replace(/[̀-ͯ]/g, "")
    .toLowerCase()
    .replace(/\s+/g, " ")
    .trim()
}

