// ── Auth validation ────────────────────────────────────────────────────────────
type FieldErrors = Record<string, string>
const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[a-zA-Z]{2,}$/
const NAME_RE = /^[A-Za-zÁÉÍÓÚÜÑáéíóúüñ' ]+$/
// Same rules under the names the production/registro code uses
const getPasswordError = (password: string) => passwordErrors(password, password).pass ?? ""
const validateAccountDocumentNumber = (value: string, docType: string) => validateDocumentNumber(value, docType)
function emailError(email: string) {
  if (!email.trim()) return "Ingresa tu correo electrónico."
  if (!EMAIL_RE.test(email.trim()))
    return "Escribe un correo válido, por ejemplo nombre@correo.com."
  return ""
}

function validateLogin(
  email: string,
  pass: string,
  savedPass?: string,
  accountStatus?: string,
  requireRegisteredAccount = false,
  accountExists = !!savedPass,
): FieldErrors {
  const e: FieldErrors = {}
  const em = emailError(email)
  if (em) e.email = em
  else if (
    accountStatus &&
    ["inactivo", "inactiva", "anulado", "anulada"].includes(
      accountStatus.trim().toLowerCase(),
    )
  ) {
    e.email = "Esta cuenta está inactiva. Contacta al administrador."
  } else if (requireRegisteredAccount && !accountExists) {
    e.email = "No encontramos una cuenta con ese correo. Regístrate para continuar."
  }
  if (!pass) e.pass = "Ingresa tu contraseña."
  else if (pass.length < 8) e.pass = "La contraseña tiene mínimo 8 caracteres."
  else if (savedPass && pass !== savedPass) e.pass = "La contraseña es incorrecta."
  return e
}

function validateRegister(f: {
  name: string
  lastname?: string
  docType: string
  docNum: string
  email: string
  phone: string
  pass: string
  pass2: string
}): FieldErrors {
  const e: FieldErrors = {}
  const name = f.name.trim()
  if (!name) e.name = "Ingresa tu nombre."
  else if (!NAME_RE.test(name)) e.name = "El nombre solo puede tener letras y espacios."
  else if (name.length < 2) e.name = "El nombre debe tener al menos 2 letras."
  if (f.lastname?.trim() && !NAME_RE.test(f.lastname.trim()))
    e.lastname = "El apellido solo puede tener letras y espacios."
  if (!f.docType) e.docType = "Selecciona el tipo de documento."
  const doc = f.docNum.trim()
  if (!doc) e.docNum = "Ingresa tu número de documento."
  else if (f.docType && !DOC_RULES[f.docType]?.re.test(doc))
    e.docNum = DOC_RULES[f.docType].msg
  const phone = f.phone.replace(/\s/g, "")
  if (phone && !/^3\d{9}$/.test(phone))
    e.phone = "El celular debe tener 10 números y empezar por 3."
  const em = emailError(f.email)
  if (em) e.email = em
  else if (loadLS(`profile:${f.email.trim().toLowerCase()}`, null))
    e.email = "Ya existe una cuenta con este correo. Inicia sesión."
  return { ...e, ...passwordErrors(f.pass, f.pass2) }
}

function passwordErrors(pass: string, pass2: string): FieldErrors {
  const e: FieldErrors = {}
  if (!pass) e.pass = "Crea una contraseña."
  else {
    const missing = [
      pass.length < 8 && "mínimo 8 caracteres",
      !/[A-Z]/.test(pass) && "una mayúscula",
      !/[a-z]/.test(pass) && "una minúscula",
      !/\d/.test(pass) && "un número",
    ].filter(Boolean)
    if (missing.length) e.pass = `La contraseña necesita ${missing.join(", ")}.`
  }
  if (!pass2) e.pass2 = "Confirma tu contraseña."
  else if (pass2 !== pass) e.pass2 = "Las contraseñas no coinciden."
  return e
}


function FieldError({ msg }: { msg?: string }) {
  if (!msg) return null
  return (
    <p className="text-[11px] leading-snug" style={{ color: C.red }} role="alert">
      {msg}
    </p>
  )
}

// ── Shared UI ──────────────────────────────────────────────────────────────────
function InputField({
  label,
  type = "text",
  placeholder,
  value,
  onChange,
  required,
  error,
  disabled,
}: {
  label: string
  type?: string
  placeholder?: string
  value: string
  onChange: (v: string) => void
  required?: boolean
  error?: string
  disabled?: boolean
}) {
  const baseBorder = error ? C.red : "rgba(30,30,30,0.12)"
  // Password fields get an eye button to show/hide what was typed
  const isPassword = type === "password"
  const [showPass, setShowPass] = useState(false)
  return (
    <div className="flex flex-col gap-1">
      <label
        className="text-xs font-semibold"
        style={{ color: "rgba(30,30,30,0.5)" }}
      >
        {label}
        {required && !label.trim().endsWith("*") && " *"}
      </label>
      <div className="relative">
        <input
          type={isPassword && showPass ? "text" : type}
          placeholder={placeholder}
          value={value}
          onChange={(e) => onChange(e.target.value)}
          required={required}
          disabled={disabled}
          aria-invalid={!!error}
          className={`w-full px-3 py-2 rounded-xl text-sm outline-none transition-all ${isPassword ? "pr-10" : ""} ${disabled ? "cursor-not-allowed opacity-60" : ""}`}
          style={{
            background: "rgba(30,30,30,0.05)",
            border: `1.5px solid ${baseBorder}`,
            color: "#1A1714",
          }}
          onFocus={(e) => (e.currentTarget.style.borderColor = error ? C.red : C.mustard)}
          onBlur={(e) => (e.currentTarget.style.borderColor = baseBorder)}
        />
        {isPassword && (
          <button
            type="button"
            onClick={() => setShowPass((s) => !s)}
            aria-label={showPass ? "Ocultar contraseña" : "Mostrar contraseña"}
            aria-pressed={showPass}
            className="absolute inset-y-0 right-0 px-3 flex items-center cursor-pointer hover:opacity-70 [&_svg]:w-4 [&_svg]:h-4"
            style={{ color: "rgba(30,30,30,0.45)" }}
          >
            {showPass ? Ico.eyeOff : Ico.eye}
          </button>
        )}
      </div>
      <FieldError msg={error} />
    </div>
  )
}

function PinCodeField({
  label,
  value,
  onChange,
  error,
}: {
  label: string
  value: string
  onChange: (value: string) => void
  error?: string
}) {
  const [focused, setFocused] = useState(false)

  return (
    <div className="flex flex-col gap-2">
      <label className="text-sm font-semibold" style={{ color: C.dark }}>
        {label}
      </label>
      <div
        className="relative"
        onClick={(event) => event.currentTarget.querySelector("input")?.focus()}
      >
        <div className="grid w-fit grid-cols-6 gap-1.5 sm:gap-2" aria-hidden="true">
          {Array.from({ length: 6 }, (_, index) => {
            const activeIndex = Math.min(value.length, 5)
            const active = focused && index === activeIndex
            return (
              <div
                key={index}
                className="flex h-9 w-9 items-center justify-center rounded-lg text-base font-bold transition-all sm:h-10 sm:w-10 sm:rounded-xl"
                style={{
                  background: "#FBF8F0",
                  border: `1.5px solid ${error ? C.red : active ? C.mustard : "rgba(182,140,28,0.2)"}`,
                  color: C.dark,
                  boxShadow: active && !error ? "0 0 0 3px rgba(182,140,28,0.12)" : "0 2px 7px rgba(54,57,63,0.04)",
                }}
              >
                {value[index] || ""}
              </div>
            )
          })}
        </div>
        <input
          type="text"
          inputMode="numeric"
          autoComplete="one-time-code"
          pattern="[0-9]*"
          maxLength={6}
          value={value}
          onChange={(event) => onChange(event.target.value.replace(/\D/g, "").slice(0, 6))}
          onFocus={() => setFocused(true)}
          onBlur={() => setFocused(false)}
          aria-label={label}
          aria-invalid={!!error}
          className="absolute inset-0 h-full w-full cursor-text opacity-0"
        />
      </div>
      <FieldError msg={error} />
    </div>
  )
}

