function LoginPage({
  onLogin,
  onRegister,
  onForgot,
  onBack,
}: {
  onLogin: (u: User) => void
  onRegister: () => void
  onForgot: () => void
  onBack: () => void
}) {
  useEffect(() => {
    window.scrollTo(0, 0)
  }, [])

  const [email, setEmail] = useState("")
  const [pass, setPass] = useState("")
  // Errors show after the first submit and update live while typing
  const [tried, setTried] = useState(false)
  const [serverErr, setServerErr] = useState("")
  const [busy, setBusy] = useState(false)
  // Password and account status are checked by the backend
  const errors = tried ? validateLogin(email, pass) : {}
  const submit = async (e: React.FormEvent) => {
    e.preventDefault()
    setTried(true)
    setServerErr("")
    if (busy || Object.keys(validateLogin(email, pass)).length) return
    setBusy(true)
    try {
      onLogin(await apiLogin(email, pass))
    } catch (err) {
      setServerErr((err as Error).message)
    } finally {
      setBusy(false)
    }
  }
  return (
    <div
      className="auth-access-page auth-login-page relative isolate min-h-screen flex items-center justify-center overflow-hidden px-4 py-8 sm:px-8"
      style={{
        background: "#080d0f",
        fontFamily: "DM Sans, sans-serif",
      }}
    >
      <AuthPhotoBackground src={loginBackgroundImg} />
      <AccessBackButton onClick={onBack} />
      <div className="relative z-10 grid w-full max-w-6xl items-center gap-8 lg:grid-cols-[minmax(0,1.1fr)_minmax(0,1fr)] lg:gap-14">
        <div className="hidden px-4 lg:block">
          <img
            src={logoImg}
            alt="El Parche"
            className="mb-5 h-36 w-36 object-contain"
          />
          <div
            className="mb-3 text-sm font-bold uppercase tracking-widest"
            style={{ color: "#D6B44B" }}
          >
            Bienvenido a El Parche
          </div>
          <h1
            className="mb-4 text-4xl font-black leading-tight"
            style={{ fontFamily: "League Spartan, sans-serif", color: "#fff" }}
          >
            Tu próximo antojo empieza aquí.
          </h1>
          <p
            className="max-w-md text-lg leading-relaxed"
            style={{ color: "rgba(255,255,255,0.88)" }}
          >
            Inicia sesión para guardar tus datos, repetir tus pedidos y seguir
            cada entrega.
          </p>
        </div>
        <div
          className="mx-auto w-full max-w-lg rounded-3xl p-5 sm:p-6"
          style={{
            background: "#fff",
            boxShadow: "0 18px 55px rgba(0,0,0,0.28)",
          }}
        >
          <div className="mb-4 flex items-center justify-center gap-3 lg:hidden">
            <img
              src={logoImg}
              alt="El Parche"
              className="h-28 w-28 object-contain"
            />
          </div>
          <h2
            className="font-black text-2xl mb-1"
            style={{ fontFamily: "League Spartan, sans-serif", color: C.dark }}
          >
            Iniciar sesión
          </h2>
          <div
            className="text-sm mb-4"
            style={{ color: "rgba(30,30,30,0.45)" }}
          >
            Accede a tu cuenta para continuar
          </div>
          <form onSubmit={submit} noValidate className="flex flex-col gap-2.5">
            <InputField
              label="Correo electrónico"
              type="email"
              placeholder="tu@correo.com"
              value={email}
              onChange={setEmail}
              required
              error={errors.email}
            />
            <InputField
              label="Contraseña"
              type="password"
              placeholder="••••••••"
              value={pass}
              onChange={setPass}
              required
              error={errors.pass}
            />
            <button
              type="button"
              onClick={onForgot}
              className="text-xs text-right cursor-pointer"
              style={{ color: C.mustard }}
            >
              ¿Olvidaste tu contraseña?
            </button>
            <FieldError msg={serverErr} />
            <button
              type="submit"
              disabled={busy}
              className="w-full py-2.5 rounded-xl font-bold text-sm cursor-pointer hover:opacity-90"
              style={{ background: C.mustard, color: "#fff" }}
            >
              {busy ? "Ingresando..." : "Iniciar sesión"}
            </button>
            <div
              className="flex items-center gap-3 text-xs"
              style={{ color: "rgba(30,30,30,0.3)" }}
            >
              <span
                className="h-px flex-1"
                style={{ background: "rgba(30,30,30,0.1)" }}
              />
              <span>o</span>
              <span
                className="h-px flex-1"
                style={{ background: "rgba(30,30,30,0.1)" }}
              />
            </div>
            <button
              type="button"
              onClick={onRegister}
              className="w-full py-2.5 rounded-xl font-bold text-sm cursor-pointer"
              style={{ background: "rgba(182,140,28,0.10)", color: C.mustard }}
            >
              Crear una cuenta
            </button>
            <button
              type="button"
              onClick={onBack}
              className="w-full py-2 rounded-xl font-medium text-sm cursor-pointer"
              style={{
                background: "rgba(30,30,30,0.05)",
                color: "rgba(30,30,30,0.5)",
              }}
            >
              ← Volver al inicio
            </button>
          </form>
        </div>
      </div>
    </div>
  )
}

function RegisterPage({
  onVerify,
  onLoginLink,
  onBack,
}: {
  onVerify: (u: User) => void
  onLoginLink: () => void
  onBack: () => void
}) {
  useEffect(() => {
    window.scrollTo(0, 0)
  }, [])

  const [tried, setTried] = useState(false)
  const [verificationPending, setVerificationPending] = useState(false)
  const [verificationCode, setVerificationCode] = useState("")
  const [form, setForm] = useState({
    name: "",
    lastname: "",
    docType: "",
    docNum: "",
    email: "",
    phone: "",
    pass: "",
    pass2: "",
  })
  const errors = tried ? validateRegister(form) : {}
  const upd = (k: keyof typeof form) => (v: string) =>
    setForm((current) => ({
      ...current,
      [k]:
        k === "docNum"
          ? normalizeAccountDocumentInput(v, current.docType)
          : k === "phone"
            ? digitsOnly(v).slice(0, 10)
            : v,
    }))

  const newUser = (): User => ({
    name: `${form.name.trim()} ${form.lastname.trim()}`.trim(),
    email: form.email.trim().toLowerCase(),
    role: "user",
    docType: form.docType,
    phone: form.phone.replace(/\s/g, ""),
    cedula: form.docNum.trim(),
  })
  const [serverErr, setServerErr] = useState("")
  const [busy, setBusy] = useState(false)
  const submitForm = async (e: React.FormEvent) => {
    e.preventDefault()
    setTried(true)
    setServerErr("")
    if (busy || Object.keys(validateRegister(form)).length) return
    setBusy(true)
    try {
      await requestRegistrationCode(newUser(), form.pass)
      setVerificationPending(true)
      setServerErr("")
    } catch (err) {
      setServerErr((err as Error).message)
    } finally {
      setBusy(false)
    }
  }
  const verifyRegistration = async (e: React.FormEvent) => {
    e.preventDefault()
    setServerErr("")
    if (!/^\d{6}$/.test(verificationCode)) {
      setServerErr("Escribe el código de 6 dígitos que te enviamos al correo.")
      return
    }
    if (busy) return
    setBusy(true)
    try {
      await verifyRegistrationCode(newUser().email, verificationCode)
      onVerify(newUser())
    } catch (err) {
      setServerErr((err as Error).message)
    } finally {
      setBusy(false)
    }
  }
  return (
    <div
      className="auth-access-page auth-register-page relative isolate min-h-screen flex items-center justify-center overflow-hidden px-4 py-8"
      style={{
        fontFamily: "DM Sans, sans-serif",
      }}
    >
      <AuthPhotoBackground src={authFoodBackgroundImg} />
      <AccessBackButton onClick={onLoginLink} />
      <div className="relative z-10 grid w-full max-w-6xl items-center gap-8 lg:grid-cols-[minmax(0,0.9fr)_minmax(0,1.1fr)] lg:gap-10">
        <div className="hidden px-5 text-white lg:block">
          <AccessLogo
            onClick={onLoginLink}
            className="mb-8 h-24 w-40 object-contain"
          />
          <h1
            className="mb-4 max-w-[400px] text-4xl font-black leading-tight"
            style={{ fontFamily: "League Spartan, sans-serif", color: "#fff" }}
          >
            Crea tu cuenta y pide más fácil.
          </h1>
          <p className="max-w-md text-lg leading-relaxed text-white/85">
            Guarda tus datos de entrega y disfruta tus hamburguesas favoritas
            sin repetir el proceso.
          </p>
        </div>
        <div
          className={`mx-auto w-full rounded-3xl ${verificationPending ? "max-w-[23rem] p-5 lg:justify-self-center" : "max-w-[600px] p-5 sm:p-6 lg:justify-self-center"}`}
          style={{
            background: "#fff",
            boxShadow: "0 18px 55px rgba(0,0,0,0.28)",
          }}
        >
          {!verificationPending && (
            <div className="mb-4 flex justify-center lg:hidden">
              <AccessLogo
                onClick={onLoginLink}
                className="h-20 w-32 object-contain"
              />
            </div>
          )}
          {verificationPending && (
            <div className="mb-2 flex items-center justify-center">
              <AccessLogo
                onClick={onLoginLink}
                className="h-36 w-36 object-contain"
              />
            </div>
          )}
          <h2
            className="font-black text-xl mb-1"
            style={{ fontFamily: "League Spartan, sans-serif", color: C.dark }}
          >
            {verificationPending ? "Verifica tu correo" : "Crear cuenta"}
          </h2>
          <div
            className={`text-sm ${verificationPending ? "mb-3" : "mb-6"}`}
            style={{ color: "rgba(30,30,30,0.45)" }}
          >
            {verificationPending
              ? <>Enviamos un código de 6 dígitos a <strong>{form.email}</strong>.</>
              : <>¿Ya tienes cuenta?{" "}
            <button
              onClick={onLoginLink}
              className="font-semibold cursor-pointer"
              style={{ color: C.mustard }}
            >
              Inicia sesión
            </button></>}
          </div>
          <form onSubmit={verificationPending ? verifyRegistration : submitForm} noValidate className={`flex flex-col gap-2.5 [&_input]:px-4 [&_input]:py-2.5 [&_select]:px-4 [&_select]:py-2.5`}>
            {verificationPending ? (
              <>
                <PinCodeField
                  label="PIN de verificación"
                  value={verificationCode}
                  onChange={setVerificationCode}
                  error={tried && !/^\d{6}$/.test(verificationCode) ? "El PIN debe tener 6 dígitos." : undefined}
                />
                <p className="text-xs" style={{ color: "rgba(30,30,30,0.55)" }}>
                  Revisa también la carpeta de correo no deseado. El código vence en 15 minutos.
                </p>
                <FieldError msg={serverErr} />
                <button
                  type="submit"
                  disabled={busy}
                  className="w-full py-2.5 rounded-xl font-bold text-sm cursor-pointer hover:opacity-90 disabled:opacity-60"
                  style={{ background: C.mustard, color: "#fff" }}
                >
                  {busy ? "Verificando..." : "Verificar y crear cuenta"}
                </button>
                <button
                  type="button"
                  onClick={() => {
                    setVerificationPending(false)
                    setVerificationCode("")
                    setServerErr("")
                  }}
                  className="w-full py-2 rounded-xl font-medium text-sm cursor-pointer"
                  style={{ background: "rgba(30,30,30,0.05)", color: "rgba(30,30,30,0.5)" }}
                >
                  ← Corregir mis datos
                </button>
              </>
            ) : (
            <>
            {/* Document type first, its number right next to it */}
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 items-start">
              <div className="flex flex-col gap-1 min-w-0">
                <label
                  className="text-xs font-semibold"
                  style={{ color: "rgba(30,30,30,0.5)" }}
                >
                  Tipo de documento *
                </label>
                <select
                  value={form.docType}
                  onChange={(e) => {
                    const docType = e.target.value
                    setForm((current) => ({
                      ...current,
                      docType,
                      docNum: normalizeAccountDocumentInput(current.docNum, docType),
                    }))
                  }}
                  aria-invalid={!!errors.docType}
                  className="w-full px-3 py-2 rounded-xl text-sm outline-none"
                  style={{
                    background: "rgba(30,30,30,0.05)",
                    border: `1.5px solid ${errors.docType ? C.red : "rgba(30,30,30,0.12)"}`,
                    color: form.docType ? "#1A1714" : "rgba(30,30,30,0.35)",
                  }}
                >
                  <option value="">Selecciona tipo...</option>
                  {DOC_TYPES.map((d) => (
                    <option key={d} value={d}>
                      {d}
                    </option>
                  ))}
                </select>
                <FieldError msg={errors.docType} />
              </div>
              <InputField
                label="Nº Documento *"
                placeholder="123456789"
                value={form.docNum}
                onChange={upd("docNum")}
                required
                error={errors.docNum}
              />
            </div>
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 items-start">
              <InputField
                label="Nombre *"
                placeholder="Tu nombre"
                value={form.name}
                onChange={upd("name")}
                required
                error={errors.name}
              />
              <InputField
                label="Apellido"
                placeholder="Tu apellido"
                value={form.lastname}
                onChange={upd("lastname")}
                error={errors.lastname}
              />
            </div>
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 items-start">
              <InputField
                label="Teléfono"
                type="tel"
                placeholder="3XX XXX XXXX"
                value={form.phone}
                onChange={upd("phone")}
                error={errors.phone}
              />
              <InputField
                label="Correo *"
                type="email"
                placeholder="tu@correo.com"
                value={form.email}
                onChange={upd("email")}
                required
                error={errors.email}
              />
            </div>
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 items-start">
              <InputField
                label="Contraseña *"
                type="password"
                placeholder="••••••••"
                value={form.pass}
                onChange={upd("pass")}
                required
                error={errors.pass}
              />
              <InputField
                label="Confirmar *"
                type="password"
                placeholder="••••••••"
                value={form.pass2}
                onChange={upd("pass2")}
                required
                error={errors.pass2}
              />
            </div>
            {!errors.pass && (
              <p className="text-[11px]" style={{ color: "rgba(30,30,30,0.45)" }}>
                Mínimo 8 caracteres, con una mayúscula, una minúscula y un número.
              </p>
            )}
            <FieldError msg={serverErr} />
            <button
              type="submit"
              disabled={busy}
              className="w-full py-2.5 rounded-xl font-bold text-sm cursor-pointer hover:opacity-90 disabled:opacity-60"
              style={{ background: C.mustard, color: "#fff" }}
            >
              {busy ? "Creando cuenta..." : "Crear cuenta →"}
            </button>
            <button
              type="button"
              onClick={onBack}
              className="w-full py-2 rounded-xl font-medium text-sm cursor-pointer"
              style={{
                background: "rgba(30,30,30,0.05)",
                color: "rgba(30,30,30,0.5)",
              }}
            >
              ← Volver al inicio
            </button>
            </>
            )}
          </form>
        </div>
      </div>
    </div>
  )
}

// After logging in with the provisional password from the sign-up e-mail
function ChooseOwnPasswordPage({
  user,
  onDone,
  onLogout,
}: {
  user: User
  onDone: () => void
  onLogout: () => void
}) {
  const [pass, setPass] = useState("")
  const [pass2, setPass2] = useState("")
  const [tried, setTried] = useState(false)
  const [serverErr, setServerErr] = useState("")
  const [busy, setBusy] = useState(false)
  const errors = tried ? passwordErrors(pass, pass2) : {}
  return (
    <AuthLayout
      title="Crea tu contraseña"
      backgroundImage={authFoodBackgroundImg}
      onBack={onLogout}
      onLogoClick={onLogout}
      sub={
        <>
          Hola <strong>{user.name}</strong>, cambia la contraseña provisional por una propia
        </>
      }
    >
      <form
        noValidate
        onSubmit={(e) => {
          e.preventDefault()
          setTried(true)
          setServerErr("")
          if (busy || Object.keys(passwordErrors(pass, pass2)).length) return
          setBusy(true)
          api<{ token: string }>("/auth/me/contrasena-inicial", "PATCH", { nueva: pass })
            .then(({ token }) => {
              saveLS("token", token) // the new token no longer carries the "must change" mark
              onDone()
            })
            .catch((err) => setServerErr((err as Error).message))
            .finally(() => setBusy(false))
        }}
        className="flex flex-col gap-3"
      >
        <InputField
          label="Nueva contraseña"
          type="password"
          placeholder="••••••••"
          value={pass}
          onChange={setPass}
          required
          error={errors.pass}
        />
        <InputField
          label="Confirmar"
          type="password"
          placeholder="••••••••"
          value={pass2}
          onChange={setPass2}
          required
          error={errors.pass2}
        />
        {!errors.pass && (
          <p className="text-[11px]" style={{ color: "rgba(30,30,30,0.45)" }}>
            Mínimo 8 caracteres, con una mayúscula, una minúscula y un número.
          </p>
        )}
        <FieldError msg={serverErr} />
        <button
          type="submit"
          disabled={busy}
          className="w-full py-3 rounded-xl font-bold text-sm cursor-pointer hover:opacity-90 disabled:opacity-60"
          style={{ background: C.mustard, color: "#fff" }}
        >
          {busy ? "Guardando..." : "Guardar y continuar"}
        </button>
        <button
          type="button"
          onClick={onLogout}
          className="w-full py-2 rounded-xl text-sm cursor-pointer"
          style={{ background: "rgba(30,30,30,0.05)", color: "rgba(30,30,30,0.5)" }}
        >
          Cerrar sesión
        </button>
      </form>
    </AuthLayout>
  )
}

function ForgotPage({
  onReset,
  onBack,
}: {
  onReset: (email: string) => void
  onBack: () => void
}) {
  const [email, setEmail] = useState("")
  const [sent, setSent] = useState(false)
  const [emailErr, setEmailErr] = useState("")
  const [busy, setBusy] = useState(false)
  if (sent)
    return (
      <AuthLayout
        title="Revisa tu correo"
        sub="Si está registrado, te llegará un código"
        backgroundImage={authFoodBackgroundImg}
        onBack={() => setSent(false)}
        onLogoClick={onBack}
        compact
      >
        <div className="text-center py-2">
          <div className="mb-3 flex justify-center" aria-hidden="true">
            <svg
              viewBox="0 0 48 48"
              fill="none"
              className="h-12 w-12"
              style={{ color: C.mustard }}
            >
              <rect x="5" y="9" width="38" height="30" rx="6" stroke="currentColor" strokeWidth="2.5" />
              <path d="m7 13 17 13 17-13" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" />
            </svg>
          </div>
          <p className="text-sm mb-5" style={{ color: "rgba(30,30,30,0.55)" }}>
            Si <strong>{email}</strong> está registrado, se le enviará un código a su correo. Vence en 15 minutos;
            si no lo ves, revisa también la carpeta de spam.
          </p>
          <button
            onClick={() => onReset(email)}
            className="w-full py-3 rounded-xl font-bold text-sm cursor-pointer"
            style={{ background: C.mustard, color: "#fff" }}
          >
            Continuar
          </button>
        </div>
      </AuthLayout>
    )
  return (
    <AuthLayout
      title="Recuperar contraseña"
      sub="Se enviará un código si el correo existe."
      backgroundImage={authFoodBackgroundImg}
      onBack={onBack}
      onLogoClick={onBack}
    >
      <form
        onSubmit={(e) => {
          e.preventDefault()
          const error = emailError(email)
          setEmailErr(error)
          if (error || busy) return
          setBusy(true)
          api("/auth/recuperar", "POST", { correo: email.trim() })
            .then(() => setSent(true))
            .catch((err) => {
              const message = (err as Error).message
              setEmailErr(
                /no está registrado|no registrado|no existe/i.test(message)
                  ? "Se enviará un código si el correo existe."
                  : message,
              )
            })
            .finally(() => setBusy(false))
        }}
        className="flex flex-col gap-3"
      >
        <InputField
          label="Correo electrónico"
          type="email"
          placeholder="tu@correo.com"
          value={email}
          onChange={(value) => {
            setEmail(value)
            if (emailErr) setEmailErr(emailError(value))
          }}
          required
          error={emailErr}
        />
        <button
          type="submit"
          disabled={busy}
          className="w-full py-3 rounded-xl font-bold text-sm cursor-pointer hover:opacity-90 disabled:opacity-60"
          style={{ background: C.mustard, color: "#fff" }}
        >
          {busy ? "Enviando..." : "Enviar código"}
        </button>
      </form>
    </AuthLayout>
  )
}

function ResetPage({ email, onDone, onBack }: { email: string; onDone: () => void; onBack: () => void }) {
  const [code, setCode] = useState("")
  const [verificationToken, setVerificationToken] = useState("")
  const [pass, setPass] = useState("")
  const [pass2, setPass2] = useState("")
  const [err, setErr] = useState("")
  const [ok, setOk] = useState(false)
  const [busy, setBusy] = useState(false)
  if (ok)
    return (
      <AuthLayout
        title="¡Listo!"
        sub="Contraseña actualizada"
        backgroundImage={authFoodBackgroundImg}
        onBack={onDone}
        onLogoClick={onDone}
        compact
      >
        <div className="text-center py-2">
          <div className="text-5xl mb-3">✅</div>
          <button
            onClick={onDone}
            className="w-full py-3 rounded-xl font-bold text-sm cursor-pointer"
            style={{ background: C.mustard, color: "#fff" }}
          >
            Iniciar sesión
          </button>
        </div>
      </AuthLayout>
    )
  return (
    <AuthLayout
      title={verificationToken ? "Nueva contraseña" : "Verifica tu correo"}
      backgroundImage={authFoodBackgroundImg}
      onBack={verificationToken
        ? () => {
            setVerificationToken("")
            setPass("")
            setPass2("")
            setErr("")
          }
        : onBack}
      onLogoClick={onDone}
      compact
      sub={
        <>
          Para <strong>{email}</strong>
        </>
      }
    >
      <form
        onSubmit={async (e) => {
          e.preventDefault()
          if (!verificationToken) {
            if (!/^\d{6}$/.test(code)) {
              setErr("El PIN debe tener 6 dígitos.")
              return
            }
            if (busy) return
            setBusy(true)
            setErr("")
            try {
              const result = await api<{ token: string }>("/auth/recuperar/verificar", "POST", {
                correo: email.trim(),
                codigo: code,
              })
              if (!result?.token) throw new Error("No se pudo validar el código. Solicita uno nuevo.")
              setVerificationToken(result.token)
            } catch (error) {
              setErr((error as Error).message)
            } finally {
              setBusy(false)
            }
            return
          }
          if (pass !== pass2) {
            setErr("Las contraseñas no coinciden.")
            return
          }
          if (pass.length < 8 || !/[A-Z]/.test(pass) || !/[a-z]/.test(pass) || !/\d/.test(pass)) {
            setErr("Usa al menos 8 caracteres, con una mayúscula, una minúscula y un número.")
            return
          }
          if (busy) return
          setBusy(true)
          setErr("")
          api("/auth/restablecer", "POST", { correo: email.trim(), token: verificationToken, nueva: pass })
            .then(() => setOk(true))
            .catch((error) => setErr((error as Error).message))
            .finally(() => setBusy(false))
        }}
        className="flex flex-col gap-3"
      >
        {!verificationToken ? (
          <>
            <p className="text-sm" style={{ color: "rgba(30,30,30,0.55)" }}>
              Ingresa el PIN de 6 dígitos enviado a <strong>{email}</strong>.
            </p>
            <PinCodeField
              label="PIN de verificación"
              value={code}
              onChange={(value) => {
                setCode(value)
                if (err) setErr("")
              }}
              error={!verificationToken ? err : undefined}
            />
          </>
        ) : (
          <>
            <InputField
              label="Nueva contraseña"
              type="password"
              placeholder="••••••••"
              value={pass}
              onChange={setPass}
              required
            />
            <InputField
              label="Confirmar nueva contraseña"
              type="password"
              placeholder="••••••••"
              value={pass2}
              onChange={setPass2}
              required
            />
          </>
        )}
        {err && verificationToken && (
          <p className="text-sm" style={{ color: C.red }} role="alert">
            {err}
          </p>
        )}
        <button
          type="submit"
          disabled={busy}
          className="w-full py-3 rounded-xl font-bold text-sm cursor-pointer hover:opacity-90 disabled:opacity-60"
          style={{ background: C.mustard, color: "#fff" }}
        >
          {busy
            ? verificationToken
              ? "Guardando..."
              : "Verificando..."
            : verificationToken
              ? "Cambiar contraseña"
              : "Continuar"}
        </button>
      </form>
    </AuthLayout>
  )
}

// Product picture: a click shows it big and complete; another click puts it back
function ZoomableImage({ src, alt, className }: { src: string; alt: string; className?: string }) {
  const [zoomed, setZoomed] = useState(false)
  return (
    <>
      <img
        src={src}
        alt={alt}
        onClick={() => setZoomed(true)}
        title="Toca para ver más grande"
        className={`${className ?? ""} cursor-zoom-in`}
      />
      {zoomed && (
        <div
          className="fixed inset-0 z-[90] flex cursor-zoom-out flex-col items-center justify-center gap-3 p-4"
          style={{ background: "rgba(0,0,0,0.85)" }}
          onClick={() => setZoomed(false)}
          role="dialog"
          aria-label={alt}
        >
          <img src={src} alt={alt} className="max-h-[80vh] max-w-[92vw] rounded-2xl object-contain shadow-2xl" />
          <span className="text-xs text-white/70">Toca para volver</span>
        </div>
      )}
    </>
  )
}

// ── Add to Cart Modal (centered, with sauces/additions) ────────────────────────
// Compact "− amount +" where the amount can also be typed (0-99). While typing it may be empty; on leaving it
// shows the real amount again
function QtyStepper({ value, onChange, label, color, text, disabledPlus }: {
  value: number
  onChange: (n: number) => void
  label: string
  color: string
  text: string
  disabledPlus?: boolean
}) {
  const [draft, setDraft] = useState<string | null>(null)
  const on = value > 0
  const btn = "flex h-6 w-6 flex-shrink-0 cursor-pointer items-center justify-center rounded-full text-sm leading-none transition-transform active:scale-90 disabled:cursor-default disabled:opacity-30"
  return (
    <div className="flex flex-shrink-0 items-center gap-0.5">
      <button type="button" onClick={() => onChange(Math.max(0, value - 1))} disabled={!on} aria-label={`Quitar ${label}`} className={btn} style={{ border: `1.5px solid ${text}40`, color: text }}>
        −
      </button>
      <input
        type="text"
        inputMode="numeric"
        value={draft ?? String(value)}
        onChange={(event) => {
          const digits = event.target.value.replace(/\D/g, "").slice(0, 2)
          setDraft(digits)
          onChange(Number(digits) || 0)
        }}
        onFocus={(event) => event.target.select()}
        onBlur={() => setDraft(null)}
        aria-label={`Cantidad de ${label}`}
        className="w-6 bg-transparent text-center text-sm font-bold tabular-nums outline-none"
        style={{ color: on ? color : text }}
      />
      <button
        type="button"
        onClick={() => onChange(Math.min(99, value + 1))}
        disabled={disabledPlus || value >= 99}
        aria-label={`Agregar ${label}`}
        className={btn}
        style={{ background: on ? color : "transparent", border: `1.5px solid ${on ? color : `${text}40`}`, color: on ? "#fff" : text }}
      >
        +
      </button>
    </div>
  )
}

function AddToCartModal({
  product: selectedProduct,
  onClose,
  onAdd,
  onCheckout,
  dark,
}: {
  product: Product
  onClose: () => void
  onAdd: (
    p: Product,
    qty: number,
    sauces: string[],
    additions: { name: string; qty: number; price: number }[],
  ) => void
  onCheckout?: () => void
  dark: boolean
}) {
  const [product, setProduct] = useState(selectedProduct)
  useEffect(() => {
    const refreshProduct = () => {
      const current = allMenuProducts().find((item) => item.id === selectedProduct.id) ??
        allMenuProducts().find((item) => item.name === selectedProduct.name)
      if (current) setProduct(current)
      else onClose()
    }
    window.addEventListener("products-refreshed", refreshProduct)
    return () => window.removeEventListener("products-refreshed", refreshProduct)
  }, [selectedProduct.id, selectedProduct.name, onClose])
  useEffect(() => setProduct(selectedProduct), [selectedProduct])
  const [qty, setQty] = useState(1)
  // What is typed in the quantity box (null = not typing, it shows qty)
  const [qtyDraft, setQtyDraft] = useState<string | null>(null)
  const MAX_QTY = 99
  const [descOpen, setDescOpen] = useState(false)
  const [selSauces, setSelSauces] = useState<string[]>([])
  const [addQtys, setAddQtys] = useState<Record<string, number>>({})
  const [beverageSize, setBeverageSize] = useState(BEVERAGE_SIZES[0]?.id ?? "")
  // Drink whose picture is shown big (click again to close)
  const [zoomBeverage, setZoomBeverage] = useState<string | null>(null)
  const [customizationTab, setCustomizationTab] = useState<"sauces" | "additions" | "beverages">("sauces")
  const isMenuExtra = ["salsas", "adiciones", "bebidas"].includes(product.cat)
  // [, sabor, tamaño] when the product is a soda («Gaseosa Coca-Cola (1.5 L)»)
  const sodaParts = SODA_RE.exec(product.name)
  // Photo width ÷ height: a vertical or square photo goes beside the details on a computer (complete, no side
  // strips); a wide one stays on top. Read from the image itself, so it fits any photo the admin uploads
  const [photoRatio, setPhotoRatio] = useState<number | null>(null)
  useEffect(() => {
    setPhotoRatio(null)
    if (!product.img) return
    const probe = new Image()
    probe.onload = () => setPhotoRatio(probe.naturalWidth / probe.naturalHeight || null)
    probe.src = product.img
  }, [product.img])
  // Computer: the photo's column, sized from the photo's proportion so it shows complete at most ~300px tall
  // (~300px tall; a wide photo gets up to 420px wide, a tall one at least 300px). Fixed per photo: nothing resizes as you use it
  const photoColW = Math.round(Math.min(420, Math.max(300, 300 * (photoRatio ?? 1.25))))
  // Cream card under the photo (the photo's curve blends into it)
  const CARD = dark ? "#1E1C18" : "#FBF6E9"
  const TEXT = dark ? "#F4EEDC" : "#1A1714"
  const MUTED = dark ? "rgba(244,238,220,0.5)" : "rgba(30,30,30,0.5)"
  const BORDER = dark ? "rgba(244,238,220,0.08)" : "rgba(30,30,30,0.08)"
  // The tabs filter: only the chosen section shows. On a computer the three share one grid cell (the others
  // just invisible), so the column keeps the tallest one's height and nothing jumps when changing tabs
  const panelClass = (tab: typeof customizationTab) =>
    isMenuExtra
      ? "hidden"
      : `min-w-0 md:[grid-area:1/1] ${customizationTab === tab ? "block" : "hidden md:invisible md:block"}`
  const toggleSauce = (s: string) =>
    setSelSauces((p) => {
      if (p.includes(s)) return p.filter((x) => x !== s)
      return p.length < 4 ? [...p, s] : p
    })
  const changeAdd = (name: string, d: number) =>
    setAddQtys((p) => ({ ...p, [name]: Math.min(99, Math.max(0, (p[name] || 0) + d)) }))
  const setAdd = (name: string, n: number) => setAddQtys((p) => ({ ...p, [name]: n }))
  const addTotal = ADDITIONS.reduce(
    (s, a) => s + (addQtys[a.name] || 0) * a.price,
    0,
  )
  const beverageTotal = BEVERAGES.reduce(
    (total, flavor) =>
      total +
      BEVERAGE_SIZES.reduce(
        (sizeTotal, size) =>
          sizeTotal +
          (addQtys[`Gaseosa ${flavor} ${size.id}`] || 0) * sodaPrice(flavor, size),
        0,
      ),
    0,
  )
  // Sizes with at least one flavour in stock (a size where everything sold out isn't offered)
  const sizesInStock = BEVERAGE_SIZES.filter(
    (size) => !SODA_INFO.size || BEVERAGES.some((f) => { const info = sodaInfo(f, size.label); return !!info && !info.agotada }),
  )
  const selectedBeverageSize =
    sizesInStock.find((size) => size.id === beverageSize) ?? sizesInStock[0] ?? { id: "", label: "", price: 0 }
  const selectedBeverageCount = BEVERAGES.reduce(
    (total, flavor) =>
      total +
      BEVERAGE_SIZES.reduce(
        (sizeTotal, size) =>
          sizeTotal + (addQtys[`Gaseosa ${flavor} ${size.id}`] || 0),
        0,
      ),
    0,
  )
  const unitPrice = product.price + addTotal + beverageTotal
  const total = unitPrice * qty
  const handleAdd = () => {
    if (product.soldOut) return
    const adds = ADDITIONS.filter((a) => (addQtys[a.name] || 0) > 0).map(
      (a) => ({ name: a.name, qty: addQtys[a.name], price: a.price }),
    )
    const beverages = BEVERAGES.flatMap((flavor) =>
      BEVERAGE_SIZES.filter(
        (size) => (addQtys[`Gaseosa ${flavor} ${size.id}`] || 0) > 0,
      ).map((size) => ({
        name: `Gaseosa ${flavor} (${size.label})`,
        qty: addQtys[`Gaseosa ${flavor} ${size.id}`],
        price: sodaPrice(flavor, size),
      })),
    )
    onAdd(product, qty, selSauces, [...adds, ...beverages])
    onClose()
  }
  const handleCheckout = () => {
    if (product.soldOut) return
    handleAdd()
    onCheckout?.()
  }

  return (
    <div
      className="fixed inset-0 z-50 flex items-center justify-center px-4"
      style={{ background: "rgba(0,0,0,0.7)" }}
      onClick={onClose}
    >
      <div
        className="relative w-full max-w-md md:max-w-4xl rounded-3xl overflow-hidden flex flex-col md:flex-row"
        style={{
          background: CARD,
          maxHeight: "92dvh",
          boxShadow: "0 20px 60px rgba(0,0,0,0.35)",
        }}
        onClick={(e) => e.stopPropagation()}
      >
        {/* Close: the window's top-right corner (z-30 keeps it above the photo so the tap closes, not zooms) */}
        <button
          type="button"
          onClick={onClose}
          aria-label="Cerrar"
          className="absolute right-3 top-3 z-30 flex h-9 w-9 cursor-pointer items-center justify-center rounded-full hover:opacity-90"
          style={{ background: "rgba(0,0,0,0.55)", color: "#fff", backdropFilter: "blur(4px)" }}
        >
          {Ico.x}
        </button>
        {/* Left on a computer (top on a phone): the whole photo at its own proportion (no strips, no crop),
            then name, price and description */}
        <div
          className="flex min-w-0 flex-shrink-0 flex-col md:w-[var(--photo-w)]"
          style={{ "--photo-w": `${photoColW}px` } as React.CSSProperties}
        >
        <div className="relative flex-shrink-0 p-3 pb-0 md:p-4 md:pr-0" style={{ background: CARD }}>
          {product.img && (
            <ZoomableImage
              src={product.img}
              alt={product.name}
              className="mx-auto block h-auto max-h-[28vh] w-auto max-w-full rounded-2xl min-[380px]:max-h-[30vh] md:max-h-none md:w-full"
            />
          )}
        </div>
        {/* Product info, like the reference: price, name, then the whole description (a phone shows 2 lines + «Ver más») */}
        <div className="flex-shrink-0 px-5 pb-1 pt-2 min-[380px]:pb-2 min-[380px]:pt-3 md:px-5 md:pb-5 md:pt-4" style={{ background: CARD }}>
          <div className="font-price text-lg font-bold leading-none md:text-xl" style={{ color: C.mustard }}>
            {product.priceStr}
          </div>
          <h3 className="mt-1 font-black text-lg leading-tight min-[380px]:text-xl md:mt-1.5" style={{ color: TEXT }}>
            {product.name}
          </h3>
          <p
            className={`mt-1 text-sm leading-relaxed md:mt-2 ${descOpen ? "" : "line-clamp-1 min-[380px]:line-clamp-2 md:line-clamp-none"}`}
            style={{ color: dark ? "rgba(244,238,220,0.62)" : "rgba(30,30,30,0.55)" }}
          >
            {product.desc}
          </p>
          {product.desc.length > 90 && (
            <button
              type="button"
              onClick={() => setDescOpen((open) => !open)}
              className="mt-0.5 cursor-pointer text-xs font-bold hover:underline md:hidden"
              style={{ color: C.mustard }}
            >
              {descOpen ? "Ver menos" : "Ver más"}
            </button>
          )}
        </div>
        </div>
        {/* Right on a computer (below on a phone): the tabs, their options and the buttons */}
        <div className="flex min-h-0 min-w-0 flex-1 flex-col">
        <div
          className="@container min-h-0 flex-1 overflow-y-auto px-4 py-1.5 sm:px-5 md:px-6 md:pt-5"
          style={{ background: CARD }}
        >
          {!isMenuExtra && <div className={`mb-1.5 grid grid-cols-3 gap-1 rounded-full p-1 md:mb-3 md:mr-10 ${dark ? "bg-white/5" : "bg-black/5"}`}>
            {([
              ["sauces", `Salsas ${selSauces.length}/4`],
              ["additions", `Adiciones ${ADDITIONS.reduce((total, item) => total + (addQtys[item.name] || 0), 0)}`],
              ["beverages", `Bebidas ${selectedBeverageCount}`],
            ] as const).map(([tab, label]) => (
              <button
                key={tab}
                type="button"
                onClick={() => setCustomizationTab(tab)}
                className="cursor-pointer rounded-full px-2 py-1.5 text-sm font-bold transition-colors"
                style={{
                  background: customizationTab === tab ? C.mustard : "transparent",
                  color: customizationTab === tab ? "#fff" : MUTED,
                }}
              >
                {label}
              </button>
            ))}
          </div>}
          {sodaParts && (() => {
            // A soda opened from the menu is already a flavour («Coca-Cola»): only its size is chosen here, among the
            // sizes in stock. Choosing one switches the window to that soda
            const [, flavor] = sodaParts
            const parts = (p: Product) => SODA_RE.exec(p.name) as RegExpExecArray
            const sizes = MENU_EXTRAS
              .filter((p) => p.cat === "bebidas" && !p.soldOut && SODA_RE.test(p.name) && parts(p)[1] === flavor)
              .sort((a, b) => sizeMl(parts(a)[2]) - sizeMl(parts(b)[2]))
            const pick = (p: Product) => {
              if (p.id === product.id) return
              setProduct(p)
              setQty(1)
              setQtyDraft(null)
            }
            return (
              <div className="md:mr-10">
                <div className="mb-2 text-[11px] font-bold uppercase tracking-wider" style={{ color: MUTED }}>
                  Elige el tamaño de tu {flavor}
                </div>
                <div className="grid grid-cols-2 gap-2 md:gap-3">
                  {sizes.map((p) => {
                    const size = parts(p)[2]
                    const on = p.id === product.id
                    return (
                      <button
                        key={p.id}
                        type="button"
                        onClick={() => pick(p)}
                        aria-pressed={on}
                        className="flex cursor-pointer items-center gap-3 rounded-2xl p-2 text-left transition-colors md:p-3"
                        style={{
                          background: on ? `${C.mustard}14` : dark ? "rgba(244,238,220,0.04)" : "#fff",
                          border: `1.5px solid ${on ? C.mustard : BORDER}`,
                        }}
                      >
                        <span className="flex h-12 w-8 flex-shrink-0 items-center justify-center overflow-hidden md:h-16 md:w-10">
                          <BeverageArt flavor={flavor} size={size} />
                        </span>
                        <span className="min-w-0">
                          <span className="block text-sm font-bold md:text-base" style={{ color: on ? C.mustard : TEXT }}>{size}</span>
                          <span className="block text-xs font-semibold" style={{ color: MUTED }}>{p.priceStr}</span>
                        </span>
                      </button>
                    )
                  })}
                </div>
                <p className="mt-3 hidden rounded-2xl px-3 py-2.5 text-xs leading-relaxed md:block" style={{ background: dark ? "rgba(244,238,220,0.05)" : "rgba(30,30,30,0.04)", color: MUTED }}>
                  Bebida fría, servida en su envase original. Solo ves los tamaños que tenemos disponibles ahora.
                </p>
              </div>
            )
          })()}
          <div className="md:grid">
          <div className={panelClass("sauces")}>
            <div className="mb-1.5 text-[11px] font-semibold max-[379px]:hidden md:mb-2" style={{ color: selSauces.length === 4 ? C.amber : MUTED }}>
              Elige hasta 4 salsas (gratis)
            </div>
            <div role="group" aria-label="Salsas" className="grid grid-cols-2 gap-1 md:gap-1.5">
              {SAUCES.map((s) => {
                const on = selSauces.includes(s)
                return (
                  <div
                    key={s}
                    className="flex min-w-0 items-center justify-between gap-1 rounded-full py-0.5 pl-3 pr-1 md:py-2.5"
                    style={{ border: `1px solid ${on ? C.mustard : BORDER}`, background: on ? `${C.mustard}12` : dark ? "rgba(244,238,220,0.03)" : "rgba(30,30,30,0.02)" }}
                  >
                    <div className="flex min-w-0 flex-1 flex-col">
                      <span className="truncate text-xs leading-tight md:text-[13px]" style={{ color: TEXT }}>{s}</span>
                    </div>
                    <button
                      type="button"
                      onClick={() => toggleSauce(s)}
                      disabled={!on && selSauces.length >= 4}
                      aria-pressed={on}
                      aria-label={on ? `Quitar salsa ${s}` : `Agregar salsa ${s}`}
                      className="flex h-6 w-6 flex-shrink-0 cursor-pointer items-center justify-center rounded-full text-sm font-bold disabled:cursor-not-allowed disabled:opacity-40"
                      style={{ background: C.mustard, color: "#fff" }}
                    >
                      {on ? "✓" : "+"}
                    </button>
                  </div>
                )
              })}
            </div>
          </div>
          <div className={panelClass("additions")}>
            <div className="mb-1.5 text-[11px] font-semibold max-[379px]:hidden md:mb-2" style={{ color: MUTED }}>
              Agrégale lo que quieras a tu {product.name.toLowerCase()}
            </div>
            {/* Two compact columns: name and «+$ price», and a − amount + you can also type in */}
            <div className="grid grid-cols-2 gap-1.5">
              {ADDITIONS.map((a) => {
                const q = addQtys[a.name] || 0
                return (
                  <div
                    key={a.name}
                    className="flex min-w-0 items-center justify-between gap-1.5 rounded-xl py-1.5 pl-2.5 pr-1.5 transition-colors"
                    style={{
                      border: `1px solid ${q ? C.mustard : BORDER}`,
                      background: q ? `${C.mustard}12` : dark ? "rgba(244,238,220,0.04)" : "#fff",
                    }}
                  >
                    <div className="flex min-w-0 flex-1 flex-col">
                      <span className="truncate text-[13px] font-semibold leading-tight" style={{ color: TEXT }} title={a.name}>
                        {a.name}
                      </span>
                      <span className="text-[11px] font-bold leading-tight" style={{ color: C.mustard }}>
                        +{fmt(a.price)}
                      </span>
                    </div>
                    <QtyStepper value={q} onChange={(n) => setAdd(a.name, n)} label={a.name} color={C.mustard} text={TEXT} />
                  </div>
                )
              })}
            </div>
          </div>
          <div className={panelClass("beverages")}>
          {!BEVERAGES.length && (
            <p className="rounded-xl px-3 py-4 text-center text-sm" style={{ background: dark ? "rgba(244,238,220,0.05)" : "rgba(30,30,30,0.04)", color: MUTED }}>
              Por ahora no hay gaseosas disponibles.
            </p>
          )}
          {BEVERAGES.length > 0 && (
          <div>
            {/* Size as visible buttons: the bottle photos below change with it */}
            <div
              role="radiogroup"
              aria-label="Tamaño de gaseosa"
              className="mb-1.5 grid gap-1.5 md:mb-2"
              style={{ gridTemplateColumns: `repeat(${Math.max(1, sizesInStock.length)}, minmax(0, 1fr))` }}
            >
              {sizesInStock.map((size) => {
                const on = size.id === selectedBeverageSize.id
                return (
                  <button
                    key={size.id}
                    type="button"
                    role="radio"
                    aria-checked={on}
                    onClick={() => setBeverageSize(size.id)}
                    className="flex cursor-pointer flex-col items-center rounded-full px-1 py-1.5 leading-tight transition-colors"
                    style={{
                      background: on ? C.mustard : dark ? "rgba(244,238,220,0.05)" : "#fff",
                      border: `1px solid ${on ? C.mustard : BORDER}`,
                      color: on ? "#fff" : TEXT,
                    }}
                  >
                    <span className="text-xs font-bold">{size.label}</span>
                    <span className="text-[10px] font-semibold" style={{ opacity: on ? 0.9 : 0.6 }}>
                      {fmt(size.price)}
                    </span>
                  </button>
                )
              })}
            </div>
            {!BEVERAGE_SIZES.length ? (
              <p className="rounded-xl px-3 py-4 text-center text-xs" style={{ background: dark ? "rgba(244,238,220,0.03)" : "#fff", color: MUTED }}>
                No hay tamaños de bebida disponibles.
              </p>
            ) : (
              <div className="grid grid-cols-2 gap-1.5">
              {BEVERAGES.map((flavor) => {
                const size = selectedBeverageSize
                const key = `Gaseosa ${flavor} ${size.id}`
                const quantity = addQtys[key] || 0
                const info = sodaInfo(flavor, size.label)
                // Only the sodas that exist as products (that flavour may not come in this size)
                if (SODA_INFO.size && (!info || info.agotada)) return null // sin stock: no se muestra
                const unavailable = info?.agotada ? "Agotada" : ""
                const soldOut = !!unavailable
                const price = sodaPrice(flavor, size)
                return (
                  // Compact: small bottle, flavour and price, and a − amount + you can also type in
                  <div
                    key={flavor}
                    className="flex min-w-0 items-center gap-1.5 rounded-xl py-1 pl-1 pr-1.5 transition-colors"
                    style={{
                      border: `1px solid ${quantity > 0 ? C.mustard : BORDER}`,
                      background: quantity > 0 ? `${C.mustard}12` : dark ? "rgba(244,238,220,0.04)" : "#fff",
                      opacity: soldOut ? 0.55 : 1,
                    }}
                  >
                    <button
                      type="button"
                      onClick={() => setZoomBeverage(flavor)}
                      aria-label={`Ver ${beverageLabel(flavor)} ${size.label} más grande`}
                      className="flex h-10 w-7 flex-shrink-0 cursor-zoom-in items-center justify-center overflow-hidden rounded-lg max-[379px]:hidden"
                      style={{ background: "#fff" }}
                    >
                      <BeverageArt flavor={flavor} size={size.label} />
                    </button>
                    {/* Flavour only (the brand is on the bottle); nowrap keeps "Coca-Cola" in one piece */}
                    <div className="flex min-w-0 flex-1 flex-col">
                      <span className="truncate whitespace-nowrap text-[13px] font-semibold leading-tight" style={{ color: TEXT }} title={beverageLabel(flavor)}>
                        {flavor}
                      </span>
                      <span className="text-[11px] font-bold leading-tight" style={{ color: soldOut ? C.red : C.mustard }}>
                        {soldOut ? unavailable : fmt(price)}
                      </span>
                    </div>
                    <QtyStepper
                      value={quantity}
                      onChange={(n) => setAdd(key, soldOut ? Math.min(n, quantity) : n)}
                      label={`gaseosa ${flavor} ${size.label}`}
                      color={C.mustard}
                      text={TEXT}
                      disabledPlus={soldOut}
                    />
                  </div>
                )
              })}
              </div>
            )}
            {zoomBeverage && (
              <div
                className="fixed inset-0 z-[80] flex cursor-zoom-out items-center justify-center p-6"
                style={{ background: "rgba(0,0,0,0.75)" }}
                onClick={() => setZoomBeverage(null)}
                role="dialog"
                aria-label={beverageLabel(zoomBeverage)}
              >
                <div className="flex flex-col items-center gap-3">
                  <div
                    className="flex h-[min(60vh,420px)] w-[min(70vw,300px)] items-center justify-center overflow-hidden rounded-2xl p-4"
                    style={{ background: "#fff" }}
                  >
                    <BeverageArt flavor={zoomBeverage} size={selectedBeverageSize.label} />
                  </div>
                  <span className="text-base font-bold text-white">
                    {beverageLabel(zoomBeverage)} · {selectedBeverageSize.label}
                  </span>
                  <span className="max-w-xs text-center text-[10px] text-white/60">Imagen de referencia del producto</span>
                  <span className="text-xs text-white/70">Toca para volver</span>
                </div>
              </div>
            )}
          </div>
          )}
          </div>
          </div>
        </div>
        {/* Purchase: total on the left; quantity and the two short buttons on the right (on a phone the
            buttons go below, side by side) */}
        <div
          className="flex w-full flex-shrink-0 flex-wrap items-center gap-x-3 gap-y-2.5 px-4 pb-4 pt-3 md:px-6 md:pb-5"
          style={{ borderTop: `1px solid ${BORDER}`, background: CARD }}
        >
          <div
            className="flex flex-shrink-0 items-center rounded-full p-0.5"
            style={{ background: dark ? "rgba(244,238,220,0.07)" : "rgba(30,30,30,0.06)" }}
          >
            <button
              type="button"
              onClick={() => setQty((q) => Math.max(1, q - 1))}
              disabled={qty <= 1}
              aria-label="Una menos"
              className="flex h-8 w-8 cursor-pointer items-center justify-center rounded-full font-bold disabled:cursor-default disabled:opacity-35"
              style={{ color: TEXT }}
            >
              −
            </button>
            {/* The quantity can be typed (1-99); while typing it may be empty, on leaving it goes back to a valid one */}
            <input
              type="text"
              inputMode="numeric"
              value={qtyDraft ?? String(qty)}
              onChange={(event) => {
                const digits = event.target.value.replace(/\D/g, "").slice(0, 2)
                setQtyDraft(digits)
                if (Number(digits) >= 1) setQty(Number(digits))
              }}
              onFocus={(event) => event.target.select()}
              onBlur={() => setQtyDraft(null)}
              aria-label="Cantidad"
              className="w-9 bg-transparent text-center text-sm font-black outline-none"
              style={{ color: TEXT }}
            />
            <button
              type="button"
              onClick={() => setQty((q) => Math.min(MAX_QTY, q + 1))}
              disabled={qty >= MAX_QTY}
              aria-label="Una más"
              className="flex h-8 w-8 cursor-pointer items-center justify-center rounded-full font-bold disabled:cursor-not-allowed disabled:opacity-40"
              style={{ background: C.mustard, color: "#fff" }}
            >
              +
            </button>
          </div>
          {/* The total lives only in the button: it goes up with the quantity, additions and drinks */}
          <button
            type="button"
            onClick={handleAdd}
            className="flex min-w-0 flex-1 cursor-pointer items-center justify-between gap-3 whitespace-nowrap rounded-full py-2.5 pl-5 pr-5 text-sm font-bold transition-opacity hover:opacity-90 [&_svg]:h-4 [&_svg]:w-4"
            style={{ background: C.mustard, color: "#fff", boxShadow: `0 4px 12px ${C.mustard}40` }}
          >
            <span className="flex items-center gap-1.5">
              {Ico.check}
              Agregar
            </span>
            <span className="font-price font-black tabular-nums">{fmt(total)}</span>
          </button>
          {onCheckout && (
            <button
              type="button"
              onClick={handleCheckout}
              className="w-full cursor-pointer whitespace-nowrap rounded-full px-4 py-2 text-[13px] font-bold transition-colors md:w-auto"
              style={{ border: `1.5px solid ${C.mustard}`, color: C.mustard, background: "transparent" }}
            >
              Finalizar compra
            </button>
          )}
        </div>
        </div>
      </div>
    </div>
  )
}

const visiblePaginationPages = (currentPage: number, totalPages: number, maxVisible = 5) => {
  const pageCount = Math.min(totalPages, maxVisible)
  const startPage = Math.min(
    Math.max(currentPage - Math.floor(pageCount / 2), 0),
    totalPages - pageCount,
  )
  return Array.from({ length: pageCount }, (_, index) => startPage + index)
}

// ── Product Catalog Grid (shared, landing + client) ────────────────────────────
function ProductCatalog({
  onAddClick,
  dark,
  paginate = true,
  compact = false,
}: {
  onAddClick: (p: Product) => void
  dark: boolean
  paginate?: boolean
  compact?: boolean
}) {
  const [activeCat, setActiveCat] = useState("todos")
  const [search, setSearch] = useState("")
  const [pg, setPg] = useState(0)
  const topRef = useRef<HTMLDivElement>(null)
  // Changing page brings the menu back into view
  const goPage = (i: number) => {
    setPg(i)
    topRef.current?.scrollIntoView({ behavior: "smooth", block: "start" })
  }
  const TEXT = dark ? "#F4EEDC" : "#1A1714"
  const MUTED = dark ? "rgba(244,238,220,0.5)" : "rgba(30,30,30,0.5)"
  const BORDER = dark ? "rgba(244,238,220,0.08)" : "rgba(30,30,30,0.08)"
  // Additions and sauces are chosen inside a product, not sold alone. A soda without stock isn't shown, and the
  // sodas show one card per flavour («Gaseosa Coca-Cola, desde $3.000»): tapping it opens its smallest size in
  // stock, and the window lets you pick the others
  const sodaCardOpens = new Map<Product, Product>()
  const catalogProducts = allMenuProducts()
    .filter((product) => !["adiciones", "salsas"].includes(product.cat) && !product.soldOut)
    .flatMap((product) => {
      const soda = SODA_RE.exec(product.name)
      if (!soda) return [product]
      const sizes = allMenuProducts()
        .filter((p) => !p.soldOut && SODA_RE.exec(p.name)?.[1] === soda[1])
        .sort((a, b) => sizeMl(SODA_RE.exec(a.name)![2]) - sizeMl(SODA_RE.exec(b.name)![2]))
      if (sizes[0] !== product) return []
      const card: Product = {
        ...product,
        name: `Gaseosa ${soda[1]}`,
        priceStr: sizes.length > 1 ? `Desde ${fmt(Math.min(...sizes.map((p) => p.price)))}` : product.priceStr,
        desc: `${sizes.map((p) => SODA_RE.exec(p.name)![2]).join(" · ")}`,
      }
      sodaCardOpens.set(card, product)
      return [card]
    })
  const openProduct = (p: Product) => onAddClick(sodaCardOpens.get(p) ?? p)
  const filtered = catalogProducts.filter(
    (p) =>
      (activeCat === "todos" || p.cat === activeCat) &&
      (!search ||
        p.name.toLowerCase().includes(search.toLowerCase()) ||
        p.desc.toLowerCase().includes(search.toLowerCase())),
  )
  const shouldPaginate =
    paginate && activeCat === "todos" && filtered.length > ITEMS_PER_PAGE && !search
  const totalPages = Math.ceil(filtered.length / ITEMS_PER_PAGE)
  const pageItems = shouldPaginate
    ? filtered.slice(pg * ITEMS_PER_PAGE, (pg + 1) * ITEMS_PER_PAGE)
    : filtered
  const visiblePages = visiblePaginationPages(pg, totalPages)
  const switchCat = (id: string) => {
    setActiveCat(id)
    setPg(0)
  }
  return (
    <div ref={topRef}>
      {/* Category tabs */}
      <div
        className="flex snap-x gap-2 overflow-x-auto pb-2 mb-4 md:flex-wrap md:overflow-visible"
        style={{ scrollbarWidth: "none" }}
        role="tablist"
        aria-label="Categorías del menú"
      >
        {MENU_CATS.filter((cat) => cat.id !== "salsas").map((cat) => {
          const active = activeCat === cat.id
          return (
            <button
              key={cat.id}
              role="tab"
              aria-selected={active}
              onClick={() => switchCat(cat.id)}
              className={`flex flex-shrink-0 snap-start cursor-pointer items-center gap-1.5 rounded-full py-1.5 pl-1.5 pr-3.5 text-sm font-semibold transition-all hover:-translate-y-px ${active ? "landing-menu-control" : ""}`}
              style={{
                background: active ? C.mustard : dark ? "rgba(255,255,255,0.05)" : "#fff",
                border: `1px solid ${active ? C.mustard : BORDER}`,
                color: active ? "#fff" : dark ? "#F4EEDC" : "#2A2622",
                boxShadow: active ? `0 6px 16px ${C.mustard}55` : "0 1px 2px rgba(0,0,0,0.04)",
              }}
            >
              <span
                className="flex h-7 w-7 items-center justify-center rounded-full"
                style={{
                  background: active ? "rgba(255,255,255,0.22)" : `${C.mustard}1A`,
                  color: active ? "#fff" : C.mustard,
                }}
              >
                {aboutIcon(18, cat.icon)}
              </span>
              <span className="whitespace-nowrap">{cat.label}</span>
            </button>
          )
        })}
      </div>
      {/* Search in catalog */}
      <div
        className="search-control flex w-full items-center gap-2 px-3 py-2.5 rounded-full mb-5 sm:max-w-md"
        style={{
          background: dark ? "#1E1C18" : "#fff",
          border: `1.5px solid ${C.mustard}`,
        }}
      >
        <span>{Ico.search}</span>
        <input
          placeholder="Buscar en el menú..."
          value={search}
          onChange={(e) => {
            setSearch(e.target.value)
            setPg(0)
          }}
          className="min-w-0 flex-1 bg-transparent text-sm outline-none"
          style={{ color: dark ? TEXT : C.dark }}
        />
        {search && (
          <button
            type="button"
            aria-label="Limpiar búsqueda"
            onClick={() => {
              setSearch("")
              setPg(0)
            }}
            className="search-clear text-sm cursor-pointer"
          >
            ×
          </button>
        )}
      </div>
      {/* Count */}
      <p className="text-xs mb-4" style={{ color: MUTED }}>
        {filtered.length} productos
        {shouldPaginate && <> · Página {pg + 1} de {Math.max(1, totalPages)}</>}
      </p>
      <div className={`grid grid-cols-2 sm:grid-cols-3 ${compact ? "gap-2" : "gap-3"} mb-5`}>
        {pageItems.length === 0 && (
          <div
            className="col-span-3 text-center py-10 text-sm"
            style={{ color: MUTED }}
          >
            Sin resultados.
          </div>
        )}
        {pageItems.map((p) => (
          <div
            key={`${p.cat}-${p.id}`}
            className="group relative cursor-pointer overflow-hidden rounded-2xl"
            style={{
              aspectRatio: compact ? "3/2" : "4/3",
              background: dark ? "#1E1C18" : "#fff",
              boxShadow: dark
                ? "0 2px 12px rgba(0,0,0,0.3)"
                : "0 2px 12px rgba(0,0,0,0.07)",
            }}
              onClick={() => openProduct(p)}
          >
            {p.img && (
              <img
                src={p.img}
                alt={p.name}
                className="absolute inset-0 h-full w-full object-cover transition-transform duration-500 group-hover:scale-105"
              />
            )}
            <div
              className={`absolute bottom-0 left-0 right-0 ${compact ? "px-2 py-1.5" : "px-3 py-2.5"}`}
              style={{ background: C.mustard }}
            >
              <div className={`truncate font-bold leading-tight text-white ${compact ? "text-xs" : "text-sm"}`}>
                {p.name}
              </div>
            </div>
            <div
              className="absolute inset-0 flex flex-col items-center justify-center p-3 text-center opacity-0 transition-opacity duration-300 group-hover:opacity-100"
              style={{ background: "rgba(10,8,5,0.85)" }}
            >
              {p.badge && (
                <span
                  className="font-label mb-2 rounded-full px-2 py-0.5 text-xs font-bold"
                  style={{ background: C.mustard, color: "#fff" }}
                >
                  {p.badge}
                </span>
              )}
              <div className="font-price mb-1 text-lg text-white">
                {p.priceStr}
              </div>
              {p.desc && (
                <p className="mb-3 text-xs leading-relaxed" style={{ color: "rgba(255,255,255,0.72)" }}>
                  {p.desc}
                </p>
              )}
              <button
                type="button"
                disabled={p.soldOut}
                onClick={(event) => {
                  event.stopPropagation()
                  openProduct(p)
                }}
                className="cursor-pointer rounded-full px-4 py-2 text-sm font-bold text-white hover:opacity-90 disabled:cursor-not-allowed"
                style={{ background: C.mustard, opacity: p.soldOut ? 0.55 : 1 }}
              >
                {p.soldOut ? "Agotado" : "+ Agregar"}
              </button>
            </div>
          </div>
        ))}
      </div>
      {/* Paginator */}
      {shouldPaginate && totalPages > 1 && (
        <div className="flex items-center justify-center gap-2">
          <button
            disabled={pg === 0}
            onClick={() => goPage(pg - 1)}
            className="pagination-control px-3 py-1.5 rounded-lg text-sm cursor-pointer disabled:opacity-30"
            style={{
              background: dark
                ? "rgba(255,255,255,0.08)"
                : "rgba(30,30,30,0.08)",
              color: MUTED,
            }}
          >
            ←
          </button>
          {visiblePages.map((i) => (
            <button
              key={i}
              onClick={() => goPage(i)}
              className="pagination-control w-8 h-8 rounded-lg text-sm font-bold cursor-pointer"
              aria-current={i === pg ? "page" : undefined}
              style={{
                background:
                  i === pg
                    ? C.mustard
                    : dark
                      ? "rgba(255,255,255,0.08)"
                      : "rgba(30,30,30,0.08)",
                color: i === pg ? "#fff" : MUTED,
              }}
            >
              {i + 1}
            </button>
          ))}
          <button
            disabled={pg >= totalPages - 1}
            onClick={() => goPage(pg + 1)}
            className="pagination-control px-3 py-1.5 rounded-lg text-sm cursor-pointer disabled:opacity-30"
            style={{
              background: dark
                ? "rgba(255,255,255,0.08)"
                : "rgba(30,30,30,0.08)",
              color: MUTED,
            }}
          >
            →
          </button>
        </div>
      )}
    </div>
  )
}

function GuestMenuPage({
  cart,
  setCart,
  onNav,
  onLogin,
  onCheckout,
}: {
  cart: CartItem[]
  setCart: React.Dispatch<React.SetStateAction<CartItem[]>>
  onNav: (href: string) => void
  onLogin: () => void
  onCheckout: () => void
}) {
  const [addProduct, setAddProduct] = useState<Product | null>(null)
  const cartCount = cart.reduce((sum, item) => sum + item.qty, 0)
  const addToCart = (
    product: Product,
    qty: number,
    sauces: string[],
    additions: { name: string; qty: number; price: number }[],
  ) => {
    setCart((items) =>
      addCartItem(items, {
        id: Date.now(),
        productId: product.id,
        name: product.name,
        description: product.desc,
        price: product.price,
        qty,
        img: product.img,
        sauces,
        additions,
      }),
    )
    setAddProduct(null)
  }

  return (
    <div
      className="min-h-screen"
      style={{
        background: "#FAF5E8",
        fontFamily: "DM Sans, sans-serif",
        color: C.dark,
      }}
    >
      <SiteHeader
        dark={false}
        cartCount={cartCount}
        onCart={onCheckout}
        onLogin={onLogin}
        onOrder={() => window.scrollTo({ top: 0, behavior: "smooth" })}
        // «Menú» is this page; the other links go to their section of the home page
        onNav={(href) => (href === "#menu" ? window.scrollTo({ top: 0, behavior: "smooth" }) : onNav(href))}
      />
      <main className="max-w-5xl mx-auto px-4 sm:px-6 py-8">
        <div className="mb-6">
          <h1
            className="font-black text-3xl"
            style={{ fontFamily: "League Spartan, sans-serif" }}
          >
            Elige tu pedido
          </h1>
          <p className="text-sm mt-1" style={{ color: "rgba(30,30,30,0.5)" }}>
            Puedes comprar como invitado. Inicia sesión al confirmar para
            guardar tus datos.
          </p>
        </div>
        <ProductCatalog
          dark={false}
          paginate={false}
          compact
          onAddClick={setAddProduct}
        />
      </main>
      {addProduct && (
        <AddToCartModal
          product={addProduct}
          onClose={() => setAddProduct(null)}
          onAdd={addToCart}
          onCheckout={onCheckout}
          dark={false}
        />
      )}
    </div>
  )
}

// ── Orders (shared by client app, profile and checkout) ───────────────────────
const ORDER_STEPS = ["Recibido", "Confirmado", "En cocina", "En camino", "Entregado"]
// Orders from this total up need the owner's confirmation
const APPROVAL_MIN = 150000

const itemTotal = (i: CartItem) =>
  (i.price + (i.additions?.reduce((a, b) => a + b.qty * b.price, 0) ?? 0)) *
  i.qty
const cartTotal = (items: CartItem[]) =>
  items.reduce((s, i) => s + itemTotal(i), 0)
const activeCartItemsFirst = (items: CartItem[]) => [
  ...items.filter((item) => item.qty > 0),
  ...items.filter((item) => item.qty === 0),
]

function loadLS<T>(key: string, fallback: T): T {
  try {
    const v = localStorage.getItem(key)
    return v ? (JSON.parse(v) as T) : fallback
  } catch {
    return fallback
  }
}
function saveLS(key: string, value: unknown) {
  try {
    localStorage.setItem(key, JSON.stringify(value))
  } catch {
    // quota exceeded / storage blocked: state stays in memory for this session
  }
}

// ── Backend (parche-backend) ───────────────────────────────────────────────────
const API_URL = import.meta.env.VITE_API_URL || "http://localhost:3000/api"
// Uploaded photos come as "/imagenes/<id>" (served by the API); other images are full URLs
const imageUrl = (u: string | undefined) => (u?.startsWith("/imagenes/") ? API_URL + u : u || "")

// Calls the backend (with the login token) and returns `data`; throws with the server's message so forms can show it
async function api<T>(path: string, method = "GET", body?: unknown, signal?: AbortSignal): Promise<T> {
  const token = loadLS<string>("token", "")
  let res: Response
  try {
    res = await fetch(API_URL + path, {
      method,
      signal,
      headers: {
        "Content-Type": "application/json",
        ...(token ? { Authorization: `Bearer ${token}` } : {}),
      },
      body: body === undefined ? undefined : JSON.stringify(body),
    })
  } catch (error) {
    if (signal?.aborted) throw error
    throw new Error("No se pudo conectar con el servidor. Intenta de nuevo.")
  }
  const json = await res.json().catch(() => ({}))
  if (!res.ok) throw new Error(json.detalles?.[0]?.mensaje || json.mensaje || "Ocurrió un error. Intenta de nuevo.")
  return json.data
}

type AuthData = {
  token: string
  usuario: {
    correo: string
    nombre: string | null
    tipo_documento: string | null
    documento: string | null
    telefono: string | null
    direcciones: string[] | null
    roles: string[]
    requiere_cambio_contrasena?: boolean
  }
  permisos: { modulo: string; privilegios: string[] }[]
  requiere_cambio_contrasena?: boolean
}

const toUser = ({ token, usuario: u, permisos, requiere_cambio_contrasena }: AuthData): User => {
  saveLS("token", token)
  return {
    permissions: permisos.filter((p) => p.privilegios.includes("VER")).map((p) => p.modulo),
    actions: Object.fromEntries(permisos.map((p) => [p.modulo, p.privilegios])),
    name: u.nombre || u.correo,
    email: u.correo.toLowerCase(),
    role: u.roles.includes("CLIENTE") ? "user" : "admin",
    docType: u.tipo_documento || undefined,
    cedula: u.documento || undefined,
    phone: u.telefono || undefined,
    addresses: u.direcciones?.length ? u.direcciones : undefined,
    mustChangePassword: !!(requiere_cambio_contrasena ?? u.requiere_cambio_contrasena),
  }
}

const apiLogin = async (email: string, pass: string) =>
  toUser(await api<AuthData>("/auth/login", "POST", { correo: email.trim(), contrasena: pass }))

type CatalogItem = {
  id: number
  nombre: string
  descripcion: string | null
  etiqueta: string | null
  precio: number
  categoria: string
  imagenes: string[]
  estado?: string | null
}

// Backend category name → menu category id (inverse of PRODUCT_CAT_LABEL)
const MENU_CAT_ID = Object.fromEntries(
  Object.entries(PRODUCT_CAT_LABEL).map(([id, label]) => [label, id]),
)

// ── Admin tables ↔ backend ─────────────────────────────────────────────────────
// Each synced admin module maps a backend record to its table row and back. The row
// keeps the record id at `idIndex` (never shown) so edits update the same record.
type Row = (string | number)[]
// eslint-disable-next-line @typescript-eslint/no-explicit-any
type DbRecord = Record<string, any>
type SyncSpec = {
  path: string
  update: "PATCH" | "PUT"
  idIndex: number
  idOf: (r: DbRecord) => number
  toRow: (r: DbRecord) => Row
  toBody: (row: Row) => Promise<DbRecord> | DbRecord
  // Rows that live only in the browser (not sent to the backend)
  localOnly?: (row: Row) => boolean
  // Backend records this module shows (default: all)
  shows?: (r: DbRecord) => boolean
  // Status changes that use their own route instead of a full update
  setStatus?: (id: string | number, row: Row) => Promise<unknown>
  // Modules to reload after a save (e.g. stock changes in Insumos)
  reloads?: string[]
  // Saves what lives in other tables once the record has its id (e.g. the ficha técnica)
  afterSave?: (id: number, row: Row) => Promise<unknown>
}

const isActiveStatus = (v: string | number | undefined) =>
  !["Inactivo", "Inactiva", "Anulado", "Anulada"].includes(String(v ?? ""))
const estadoOf = (v: string | number | undefined) => (isActiveStatus(v) ? "ACTIVO" : "INACTIVO")
const text = (v: string | number | undefined) => String(v ?? "").trim()
// Optional e-mails must be omitted (not "") or the backend rejects them
const optionalEmail = (v: string | number | undefined) => text(v) || undefined
const withId = (row: Row, idIndex: number, id: number) => {
  row[idIndex] = id
  return row
}

// Finds a backend record id by its name (same name matching as the admin: no accents/case)
async function idByName(path: string, nameKey: string, idKey: string, name: string | number, what: string) {
  const record = (await api<DbRecord[]>(path)).find((r) => normalizeName(r[nameKey]) === normalizeName(name))
  if (!record) throw new Error(`${what} «${name}» no existe en la base de datos.`)
  return record[idKey] as number
}
const categoryIdByName = async (path: string, name: string | number) => {
  const categories = await api<DbRecord[]>(path)
  const requested = normalizeName(name)
  const aliases = requested === "gaseosas" || requested === "bebidas" ? ["gaseosas", "bebidas"] : [requested]
  const category = categories.find((item) => aliases.includes(normalizeName(item.nombre_categoria)))
  if (!category) throw new Error(`La categoría «${name}» no existe en la base de datos.`)
  return category.id_categoria as number
}

// ── Dashboard period ─────────────────────────────────────────────────────────
type DashPeriod = "hoy" | "semana" | "mes" | "año"
const MONTHS_SHORT = ["Ene", "Feb", "Mar", "Abr", "May", "Jun", "Jul", "Ago", "Sep", "Oct", "Nov", "Dic"]
const toIsoDate = (d: Date) =>
  `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`
const addDays = (d: Date, n: number) => new Date(d.getFullYear(), d.getMonth(), d.getDate() + n)

// Range [start, end) of the chosen day / week (Mon-Sun) / month / year that contains `anchor`,
// its chart buckets, the previous range of the same kind (for the % change) and a title
function getDashPeriod(kind: DashPeriod, anchor: Date) {
  const day = new Date(anchor.getFullYear(), anchor.getMonth(), anchor.getDate())
  const short = (d: Date) => `${d.getDate()} ${MONTHS_SHORT[d.getMonth()].toLowerCase()}`
  if (kind === "hoy") {
    return {
      start: day,
      end: addDays(day, 1),
      prevStart: addDays(day, -1),
      buckets: [{ label: short(day), start: day, end: addDays(day, 1) }],
      title: day.toLocaleDateString("es-CO", { weekday: "long", day: "numeric", month: "long", year: "numeric" }),
    }
  }
  if (kind === "semana") {
    const start = addDays(day, -((day.getDay() + 6) % 7)) // Monday
    return {
      start,
      end: addDays(start, 7),
      prevStart: addDays(start, -7),
      buckets: Array.from({ length: 7 }, (_, i) => {
        const d = addDays(start, i)
        return { label: `${d.toLocaleDateString("es-CO", { weekday: "short" })} ${d.getDate()}`, start: d, end: addDays(d, 1) }
      }),
      title: `Semana del ${short(start)} al ${short(addDays(start, 6))} de ${addDays(start, 6).getFullYear()}`,
    }
  }
  if (kind === "mes") {
    const start = new Date(day.getFullYear(), day.getMonth(), 1)
    const end = new Date(day.getFullYear(), day.getMonth() + 1, 1)
    const buckets = []
    for (let d = start, n = 1; d < end; d = addDays(d, 7), n++) {
      const e = addDays(d, 7) < end ? addDays(d, 7) : end
      buckets.push({ label: `Sem ${n} (${d.getDate()}-${addDays(e, -1).getDate()})`, start: d, end: e })
    }
    return {
      start,
      end,
      prevStart: new Date(day.getFullYear(), day.getMonth() - 1, 1),
      buckets,
      title: start.toLocaleDateString("es-CO", { month: "long", year: "numeric" }),
    }
  }
  const start = new Date(day.getFullYear(), 0, 1)
  return {
    start,
    end: new Date(day.getFullYear() + 1, 0, 1),
    prevStart: new Date(day.getFullYear() - 1, 0, 1),
    buckets: MONTHS_SHORT.map((label, m) => ({
      label,
      start: new Date(day.getFullYear(), m, 1),
      end: new Date(day.getFullYear(), m + 1, 1),
    })),
    title: String(day.getFullYear()),
  }
}
// Moves the anchor one period back (-1) or forward (+1)
const shiftDashAnchor = (kind: DashPeriod, anchor: Date, step: number) =>
  kind === "hoy"
    ? addDays(anchor, step)
    : kind === "semana"
      ? addDays(anchor, 7 * step)
      : kind === "mes"
        ? new Date(anchor.getFullYear(), anchor.getMonth() + step, 1)
        : new Date(anchor.getFullYear() + step, 0, 1)
const isFutureDashAnchor = (kind: DashPeriod, anchor: Date, now = new Date()) => {
  const today = new Date(now.getFullYear(), now.getMonth(), now.getDate())
  const candidateStart =
    kind === "hoy"
      ? new Date(anchor.getFullYear(), anchor.getMonth(), anchor.getDate())
      : kind === "semana"
        ? getDashPeriod("semana", anchor).start
        : kind === "mes"
          ? new Date(anchor.getFullYear(), anchor.getMonth(), 1)
          : new Date(anchor.getFullYear(), 0, 1)
  const currentStart =
    kind === "hoy"
      ? today
      : kind === "semana"
        ? getDashPeriod("semana", today).start
        : kind === "mes"
          ? new Date(today.getFullYear(), today.getMonth(), 1)
          : new Date(today.getFullYear(), 0, 1)
  return candidateStart > currentStart
}

// "Cliente mostrador": anonymous client for sales to people who don't give their details.
// Created by the backend (init.sql); it can't be edited, deactivated or deleted.
const COUNTER_CLIENT_DOC = "000000000"
// Clientes row: [0 nombre, 1 tipo doc, 2 documento, 3 teléfono, 4 correo, 5 dirección, 6 de local, 7 estado]
const isCounterClientRow = (sec: string, row: (string | number)[] | undefined) =>
  sec === "clientes" && String(row?.[2] ?? "").replace(/\D/g, "") === COUNTER_CLIENT_DOC

// Staff: any role except Cliente
const isStaffRole = (rol: string | number | undefined) => !!String(rol ?? "").trim() && String(rol).trim().toLowerCase() !== "cliente"

// Superadministrador: always this account; nobody can deactivate, delete it, change its role or e-mail
const SUPER_ADMIN_EMAIL = "admin@minifood.com"
// Usuarios row: [0 nombre, 1 tipo doc, 2 documento, 3 rol, 4 correo, 5 estado, ...]
const isSuperAdminRow = (sec: string, row: (string | number)[] | undefined) =>
  sec === "usuarios" && String(row?.[4] ?? "").trim().toLowerCase() === SUPER_ADMIN_EMAIL

// Supplier that is a person, not a company: no NIT nor contact person (row/form key 15)
const isNaturalSupplier = (tipo: string | number | undefined) => String(tipo ?? "") === "Persona natural"
// "CC 1020304050" from the supplier row's document type (8) and number (9)
const DOC_SHORT: Record<string, string> = { "Cédula de Ciudadanía": "CC", "Cédula Extranjería": "CE", NIT: "NIT", Pasaporte: "PA" }
const supplierDocument = (row: Row) =>
  [DOC_SHORT[String(row[8] ?? "")] ?? row[8], row[9]].map((v) => String(v ?? "").trim()).filter(Boolean).join(" ") || "—"
// Natural person form, in display order (the view shows the saved full name, key 0)
const NATURAL_SUPPLIER_KEYS = ["15", "8", "9", "10", "11", "3", "2", "5", "7"]
const NATURAL_SUPPLIER_VIEW_KEYS = ["15", "0", "8", "9", "3", "2", "5", "7"]
// "7" (insumos que vende) is optional: Compras already warns when a supplier has none
const supplierRequiredKeys = (draft: Record<string, string>) =>
  isNaturalSupplier(draft["15"])
    ? ["15", "8", "9", "10", "11", "3", "2", "5"]
    : ["15", "0", "1", "2", "3", "5", "8", "9", "10", "11", "12", "13", "14"]

// "Cebolla, Tomate" -> ["Cebolla", "Tomate"] (insumos a supplier sells)
const splitNames = (value: string | number | undefined) =>
  String(value ?? "").split(",").map((name) => name.trim()).filter(Boolean)

// Ficha técnica of an insumo: "Azúcar (50 g), Limón (2 und)" -> [{ name: "Azúcar", quantity: "50" }, ...]
const parseMainSupplies = (value: string | number | undefined) =>
  splitNames(value).map((part) => {
    const match = /^(.*?)\s*\(\s*([\d.]+)\s*([^)]*)\)$/.exec(part)
    return match
      ? { name: match[1], quantity: match[2], unit: match[3].trim() }
      : { name: part, quantity: "", unit: "" }
  })

// Suggested units for an insumo bought in `base` (the recipe can type any other, e.g. "cucharada")
const compatibleUnits = (base: string) =>
  base === "kg" || base === "g" ? ["g", "kg"] : base === "L" || base === "ml" ? ["ml", "L"] : base === "paq" ? ["paq", "und"] : [base || "und"]
const RECIPE_UNIT_SUGGESTIONS = ["g", "kg", "ml", "L", "und", "paq", "cucharada", "cucharadita", "taza", "pizca", "tajada", "porción"]
const UNIT_FACTOR: Record<string, { kind: string; factor: number }> = {
  g: { kind: "masa", factor: 1 },
  kg: { kind: "masa", factor: 1000 },
  ml: { kind: "volumen", factor: 1 },
  L: { kind: "volumen", factor: 1000 },
}
// Quantity in the insumo's own unit, to price it (50 g of an insumo bought by kg = 0.05).
// null when it can't be converted (e.g. "cucharada" of something bought by kg)
const toBaseQuantity = (quantity: number, unit: string, base: string) => {
  if (unit.trim().toLowerCase() === base.trim().toLowerCase()) return quantity
  const from = UNIT_FACTOR[unit.trim()]
  const to = UNIT_FACTOR[base.trim()]
  return from && to && from.kind === to.kind ? (quantity * from.factor) / to.factor : null
}
// Units a product recipe can use for an insumo stocked in `base` (only ones that convert: g ↔ kg, ml ↔ L)
const convertibleUnits = (base: string) => compatibleUnits(base).filter((unit) => toBaseQuantity(1, unit, base) !== null)
// Same as toBaseQuantity, NaN when it can't be converted
const convertQty = (quantity: number, from: string, to: string) => toBaseQuantity(quantity, from, to) ?? NaN

// Colombian address: "Carrera 45A # 12 Sur - 08, Interior 2, Apartamento (Torre 3, Apto 402)".
// Housing details are optional; "named" types put the first one after the type ("Edificio Torres del Sol")
const ADDRESS_VIAS = ["Calle", "Carrera", "Avenida", "Diagonal", "Transversal", "Circular"]
const HOUSING: Record<string, { named: boolean; prefixes: string[]; labels: string[] }> = {
  Casa: { named: false, prefixes: ["Casa", "Conjunto"], labels: ["Número de casa", "Conjunto o urbanización"] },
  Apartamento: { named: false, prefixes: ["Torre", "Apto", "Conjunto"], labels: ["Torre o bloque", "Apartamento", "Conjunto"] },
  Edificio: { named: true, prefixes: ["", "Piso", "Oficina"], labels: ["Nombre del edificio", "Piso", "Oficina o local"] },
  Empresa: { named: true, prefixes: ["", "Piso/Oficina"], labels: ["Nombre de la empresa", "Piso u oficina"] },
}
type AddressParts = Record<string, string>
const composeAddress = (p: AddressParts) => {
  if (!p.via || !p.num || !p.cruce || !p.placa) return ""
  let text = `${p.via} ${p.num} # ${p.cruce} - ${p.placa}`
  if (p.interior) text += `, Interior ${p.interior}`
  const housing = HOUSING[p.tipo]
  if (housing) {
    const details = housing.prefixes
      .map((prefix, i) => ((i === 0 && housing.named) || !p[`d${i}`] ? "" : `${prefix} ${p[`d${i}`]}`))
      .filter(Boolean)
    text += `, ${p.tipo}${housing.named && p.d0 ? ` ${p.d0}` : ""}${details.length ? ` (${details.join(", ")})` : ""}`
  }
  return text
}
// Back to its parts; null when the text has another format (e.g. typed by hand)
const parseAddress = (text: string): AddressParts | null => {
  const m = /^(\S+)\s+(.+?)\s*#\s*(.+?)\s*-\s*([^,]+?)(?:,\s*Interior\s+([^,]+?))?(?:,\s*(Casa|Apartamento|Edificio|Empresa)(?:\s+([^(]+?))?(?:\s*\((.*)\))?)?$/.exec(text.trim())
  if (!m || !ADDRESS_VIAS.includes(m[1])) return null
  const parts: AddressParts = { via: m[1], num: m[2], cruce: m[3], placa: m[4], interior: m[5] ?? "", tipo: m[6] ?? "" }
  const housing = HOUSING[parts.tipo]
  const details = (m[8] ?? "").split(/,\s*/)
  housing?.prefixes.forEach((prefix, i) => {
    if (i === 0 && housing.named) parts.d0 = m[7] ?? ""
    else parts[`d${i}`] = details.find((d) => d.startsWith(`${prefix} `))?.slice(prefix.length + 1) ?? ""
  })
  return parts
}

// A loss sent back to its purchase (its quantity went back to stock)
const RETURNED_LOSS = "Devuelta a compra"
const isReturnedLoss = (row?: Row) => String(row?.[6] ?? "") === RETURNED_LOSS

// Purchase items text: one "insumo | cantidad | costo unitario" per line
const parsePurchaseLines = (value: string | number | undefined) =>
  String(value ?? "")
    .split(/\n|;/)
    .map((line) => line.split("|").map((part) => part.trim()))
    .filter(([name]) => name)
    .map(([name, quantity, unitPrice]) => ({ name, quantity: Number(quantity) || 0, unitPrice: Number(unitPrice) || 0 }))

// reloads: the module whose rows show the category by name (a rename must reach them)
const categorySpec = (path: string, reloads: string[]): SyncSpec => ({
  path,
  update: "PUT",
  idIndex: 3,
  idOf: (c) => c.id_categoria,
  toRow: (c) =>
    withId([c.nombre_categoria, c.descripcion || "", c.estado === "ACTIVO" ? "Activa" : "Inactiva"], 3, c.id_categoria),
  toBody: (row) => ({ nombre_categoria: text(row[0]), descripcion: text(row[1]), estado: estadoOf(row[2]) }),
  reloads,
})

// Backend role names are uppercase (ADMINISTRADOR); the admin shows them as "Administrador"
const roleLabel = (name: string) => name.toLowerCase().replace(/(^|\s)\S/g, (c) => c.toUpperCase())

const DB_SYNC: Record<string, SyncSpec> = {
  // [0 nombre, 1 descripción, 2 estado]. The permissions matrix is still kept in the browser.
  roles: {
    path: "/roles",
    update: "PUT",
    idIndex: 3,
    idOf: (r) => r.id_rol,
    toRow: (r) =>
      withId([roleLabel(r.nombre_rol), r.descripcion || "", r.estado === "ACTIVO" ? "Activo" : "Inactivo"], 3, r.id_rol),
    toBody: (row) => ({ nombre_rol: text(row[0]), descripcion: text(row[1]), estado: estadoOf(row[2]) }),
  },
  // [0 nombre, 1 tipo doc, 2 documento, 3 rol, 4 correo, 5 estado, 6 contraseña, 7 id, 8 admin principal]
  usuarios: {
    path: "/usuarios",
    update: "PATCH",
    idIndex: 7,
    idOf: (u) => u.id_usuario,
    toRow: (u) => {
      const row = withId(
        [u.nombre || "", u.tipo_documento || "", u.documento || "", roleLabel(u.roles?.[0] || ""), u.correo,
          u.estado === "ACTIVO" ? "Activo" : "Inactivo", ""],
        7,
        u.id_usuario,
      )
      row[8] = u.es_administrador_principal ? "Principal" : ""
      row[9] = u.telefono || ""
      row[10] = u.barrio || ""
      row[11] = u.direccion || ""
      row[12] = u.telefono_emergencia || ""
      row[13] = u.correo_personal || ""
      return row
    },
    toBody: (row) => {
      const rol = text(row[3]).toUpperCase()
      return {
        nombre: text(row[0]),
        tipo_documento: text(row[1]),
        documento: text(row[2]),
        roles: [rol],
        tipo: rol === "CLIENTE" ? "CLIENTE" : "EMPLEADO",
        correo: text(row[4]),
        estado: estadoOf(row[5]),
        contrasena: text(row[6]) || undefined,
        telefono: text(row[9]),
        barrio: text(row[10]),
        direccion: text(row[11]),
        telefono_emergencia: text(row[12]),
        correo_personal: text(row[13]),
      }
    },
    // clientes: a user with the Cliente role is also a client (it shows up there right away)
    reloads: ["clientes"],
  },
  // [0 nombre, 1 categoría, 2 precio, 3 descripción, 4 estado, 5-9 ficha técnica, 10 disponibilidad, 11 id,
  //  12 stock y 13 costo (solo cambian en las gaseosas: los mueven sus compras y ventas)]
  producto: {
    path: "/productos",
    update: "PATCH",
    idIndex: 11,
    idOf: (p) => p.id_insumo_producto,
    toRow: (p) => {
      const row = withId(
        [p.nombre, currentCategory(p.nombre_categoria), p.precio, p.descripcion || "", p.estado === "ACTIVO" ? "Activo" : "Inactivo",
          p.ficha?.nombre || `Ficha ${p.nombre}`, p.ficha?.version || "v1.0", p.ficha?.insumos_principales || "",
          p.ficha?.preparacion || "",
          JSON.stringify((p.ficha?.ingredientes || []).map((i: DbRecord) => ({ name: i.insumo, quantity: i.cantidad, unit: i.medida || "" }))),
          "Disponible"],
        11,
        p.id_insumo_producto,
      )
      row[12] = Number(p.stock) || 0
      row[13] = Number(p.costo) || 0
      row[14] = Number(p.minimo) || 0
      return row
    },
    toBody: async (row) => ({
      nombre: text(row[0]),
      id_categoria: await categoryIdByName("/categorias-productos", row[1]),
      precio: Number(row[2]),
      descripcion: text(row[3]),
      estado: estadoOf(row[4]),
      ...(row[1] === SODA_PRODUCT ? { minimo: text(row[14]) === "" ? SODA_LOW_STOCK : Number(row[14]) } : {}),
    }),
    localOnly: (row) => row[1] === "Producto de insumo",
    afterSave: (id, row) => {
      // A soda has no ficha técnica
      if (row[1] === SODA_PRODUCT) return Promise.resolve()
      let recipe: TechnicalIngredient[] = []
      try {
        recipe = JSON.parse(String(row[9] || "[]"))
      } catch {
        // unreadable recipe: saved without ingredients
      }
      if (!text(row[5]) && !text(row[7]) && !text(row[8]) && recipe.length === 0)
        return Promise.resolve()
      return api(`/productos/${id}/ficha`, "PUT", {
        nombre: text(row[5]),
        version: text(row[6]),
        insumos_principales: text(row[7]),
        preparacion: text(row[8]),
        ingredientes: recipe
          .filter((i) => Number(i.quantity) > 0)
          .map((i) => ({ insumo: i.name, cantidad: Number(i.quantity), medida: i.unit || undefined })),
      })
    },
  },
  "cat-producto": categorySpec("/categorias-productos", ["producto"]),
  // [0 nombre, 1 tipo doc, 2 documento, 3 teléfono, 4 correo, 5 dirección, 6 de local (Sí/No), 7 estado]
  // Customers who registered in the app also show up here (their e-mail is their login).
  clientes: {
    path: "/clientes",
    update: "PATCH",
    idIndex: 8,
    idOf: (c) => c.id_persona,
    toRow: (c) =>
      withId(
        [c.nombre, c.tipo_documento || "", c.documento || "", c.telefono || "", c.correo || "", c.direccion || "",
          c.de_local ? "Sí" : "No", c.estado === "ACTIVO" ? "Activo" : "Inactivo", "",
          JSON.stringify(c.direcciones || []), "", c.id_usuario ? "Sí" : "No", c.id_usuario ?? ""],
        8,
        c.id_persona,
      ),
    toBody: (row) => ({
      nombre: text(row[0]),
      tipo_documento: text(row[1]),
      documento: text(row[2]),
      telefono: text(row[3]),
      correo: optionalEmail(row[4]),
      direccion: text(row[5]),
      de_local: text(row[6]).toLowerCase() === "sí",
      estado: estadoOf(row[7]),
    }),
    reloads: ["usuarios"],
  },
  domicilios: {
    path: "/barrios/admin",
    update: "PATCH",
    idIndex: 5,
    idOf: (d) => d.id_barrio,
    toRow: (d) =>
      withId(
        [d.nombre || "", d.es_cercano ? "Sí" : "No", d.tiempo_desplazamiento_minutos ?? "",
          d.costo_domicilio_cop ?? "", d.activo ? "Activo" : "Inactivo"],
        5,
        d.id_barrio,
      ),
    toBody: (row) => ({
      nombre: text(row[0]),
      es_cercano: text(row[1]).toLowerCase() === "sí",
      tiempo_desplazamiento_minutos: text(row[2]) ? Number(row[2]) : null,
      costo_domicilio_cop: text(row[3]) ? Number(row[3]) : null,
      activo: estadoOf(row[4]) === "ACTIVO",
    }),
    reloads: ["domicilios"],
  },
  "cat-insumos": categorySpec("/categorias-insumos", ["insumos"]),
  // [0 nombre, 1 categoría, 2 unidad, 3 costo, 4 stock, 5 mínimo, 6 (sin uso), 7 producto de insumo,
  //  8-11 ficha técnica, 12 estado]. The ficha técnica texts are not in the backend yet.
  insumos: {
    path: "/insumos",
    update: "PATCH",
    idIndex: 13,
    idOf: (i) => i.id_insumo_producto,
    toRow: (i) =>
      withId(
        [i.nombre, i.nombre_categoria, i.medida || "und", i.costo, i.stock, i.minimo, "",
          i.tiene_ficha_tecnica ? "Sí" : "No",
          i.tiene_ficha_tecnica ? i.ficha?.nombre || `Ficha técnica - ${i.nombre}` : "",
          i.tiene_ficha_tecnica ? i.ficha?.version || "v1.0" : "",
          i.ficha?.insumos_principales || "", i.ficha?.preparacion || "", i.estado === "ACTIVO" ? "Activo" : "Inactivo"],
        13,
        i.id_insumo_producto,
      ),
    toBody: async (row) => ({
      nombre: text(row[0]),
      id_categoria: await categoryIdByName("/categorias-insumos", row[1]),
      medida: text(row[2]),
      // Only on create: afterwards purchases, losses and production own cost and stock
      ...(row[13] ? {} : { costo: Number(row[3]) || 0, stock: 0 }),
      minimo: Number(row[5]) || 0,
      tiene_ficha_tecnica: text(row[7]).toLowerCase() === "sí",
      estado: estadoOf(row[12]),
    }),
    // Cost and stock come back from the backend (they don't change when editing);
    // producto: a new unit also reaches the fichas técnicas that use it (the backend aligns them)
    reloads: ["insumos", "producto"],
    afterSave: (id, row) =>
      text(row[7]).toLowerCase() === "sí"
        ? api(`/insumos/${id}/ficha`, "PUT", {
            nombre: text(row[8]),
            version: text(row[9]),
            insumos_principales: text(row[10]),
            preparacion: text(row[11]),
            // no recipe lines in the insumo form: the backend keeps the saved ones
          })
        : Promise.resolve(),
  },
  // [0 proveedor, 1 fecha compra, 2 fecha registro, 3 subtotal, 4 total, 5 estado (Activo/Anulado), 6 insumos]
  // The backend adds the insumos to stock (and takes them back when the purchase is anulada).
  compras: {
    path: "/compras",
    update: "PUT",
    idIndex: 7,
    idOf: (c) => c.id_compra,
    toRow: (c) =>
      withId(
        [c.proveedor, c.fecha, c.fecha_registro, c.subtotal, c.total, c.estado === "REGISTRADA" ? "Activo" : "Anulado",
          c.detalles.map((d: DbRecord) => `${d.insumo} | ${d.cantidad} | ${d.costo_unitario}`).join("\n")],
        7,
        c.id_compra,
      ),
    toBody: async (row) => {
      const lines = parsePurchaseLines(row[6])
      // A soda is bought as its product of «Bebidas» (its stock goes there), the rest as insumos
      const [insumos, productos] = await Promise.all([
        api<DbRecord[]>("/insumos"),
        lines.some((l) => isSodaName(l.name)) ? api<DbRecord[]>("/productos") : Promise.resolve([] as DbRecord[]),
      ])
      const find = (name: string) =>
        (isSodaName(name) ? productos : insumos).find((i) => normalizeName(i.nombre) === normalizeName(name))
      const items = lines.map((line) => {
        const insumo = find(line.name)
        if (!insumo)
          throw new Error(
            isSodaName(line.name)
              ? `La gaseosa «${line.name}» no existe en Productos → Bebidas.`
              : `El insumo «${line.name}» no existe en la base de datos.`,
          )
        return { id_insumo_producto: insumo.id_insumo_producto, cantidad: line.quantity, costo_unitario: line.unitPrice }
      })
      return {
        id_proveedor: await idByName("/proveedores", "nombre", "id_proveedor", row[0], "El proveedor"),
        fecha: text(row[1]),
        iva: Math.max(0, Number(row[4]) - Number(row[3]) || 0),
        items,
      }
    },
    setStatus: (id, row) => api(`/compras/${id}/estado`, "PATCH", { estado: isActiveStatus(row[5]) ? "REGISTRADA" : "ANULADA" }),
    // producto: a soda's stock and cost live in its product
    reloads: ["insumos", "producto"],
  },
  // [0 insumo, 1 cantidad con unidad ("0.5 kg"), 2 motivo, 3 responsable, 4 fecha, 5 origen]
  // The backend takes the quantity out of the insumo's stock.
  perdidas: {
    path: "/perdidas-insumos",
    update: "PUT",
    idIndex: 9,
    idOf: (p) => p.id_perdida,
    // [.., 9 id, 10 id_compra (the purchase it was sent from)]
    toRow: (p) => {
      const row = withId(
        [p.insumo, `${p.cantidad} ${p.medida || ""}`.trim(), p.motivo || "", p.responsable || "", p.fecha, p.observacion || "",
          p.estado === "DEVUELTA" ? RETURNED_LOSS : p.cantidad_devuelta > 0 ? "Devuelta en parte" : "Registrada",
          p.motivo_devolucion || "", p.cantidad_devuelta ? `${p.cantidad_devuelta} ${p.medida || ""}`.trim() : ""],
        9,
        p.id_perdida,
      )
      row[10] = p.id_compra ?? ""
      return row
    },
    toBody: async (row) => {
      const cantidad = parseFloat(String(row[1]).replace(",", "."))
      if (!(cantidad > 0)) throw new Error(`La cantidad «${row[1]}» no es válida.`)
      return {
        // a soda sent to loss from its purchase is its product of «Bebidas»
        id_insumo_producto: isSodaName(row[0])
          ? await idByName("/productos", "nombre", "id_insumo_producto", row[0], "La gaseosa")
          : await idByName("/insumos", "nombre", "id_insumo_producto", row[0], "El insumo"),
        cantidad,
        motivo: text(row[2]),
        responsable: text(row[3]),
        fecha: text(row[4]) || undefined,
        observacion: text(row[5]),
        // Only set when sent from a purchase; an edit leaves the saved link as it is
        id_compra: Number(row[10]) || undefined,
      }
    },
    // perdidas too: the new row gets its estado from the backend
    reloads: ["insumos", "perdidas"],
  },
  // [0 nombre, 1 NIT, 2 correo, 3 teléfono, 4 contacto, 5 dirección, 6 estado, 7 insumos,
  //  8-14 contacto: tipo doc, nº doc, nombre, apellido, teléfono, correo, cargo]
  proveedores: {
    path: "/proveedores",
    update: "PATCH",
    idIndex: 16,
    idOf: (p) => p.id_proveedor,
    // Nombre/apellido (10, 11) stay empty: the edit form splits them from "contacto"
    toRow: (p) =>
      withId(
        [p.nombre, p.nit || "", p.correo || "", p.telefono || "", p.contacto || "", p.direccion || "",
          p.estado === "ACTIVO" ? "Activo" : "Inactivo", p.insumos || "", p.contacto_tipo_documento || "",
          p.contacto_documento || "", "", "", p.contacto_telefono || "", p.contacto_correo || "", p.contacto_cargo || "",
          p.tipo || "Persona jurídica"],
        16,
        p.id_proveedor,
      ),
    toBody: (row) => ({
      nombre: text(row[0]),
      nit: text(row[1]),
      correo: optionalEmail(row[2]),
      telefono: text(row[3]),
      contacto: text(row[4]),
      direccion: text(row[5]),
      estado: estadoOf(row[6]),
      insumos: text(row[7]),
      contacto_tipo_documento: text(row[8]),
      contacto_documento: text(row[9]),
      contacto_telefono: text(row[12]),
      contacto_correo: optionalEmail(row[13]),
      contacto_cargo: text(row[14]),
      tipo: text(row[15]) || "Persona jurídica",
    }),
  },
}

// Creates (no id yet) or updates the row's record in the backend; returns its id
async function saveRowToDb(spec: SyncSpec, row: Row) {
  const body = await spec.toBody(row)
  const id = row[spec.idIndex]
  const saved = id
    ? await api<DbRecord>(`${spec.path}/${id}`, spec.update, body)
    : await api<DbRecord>(spec.path, "POST", body)
  return { id: spec.idOf(saved), saved }
}

// ── Permissions ↔ backend ──────────────────────────────────────────────────────
// Panel section -> backend module (also the names of the permissions matrix)
const SECTION_MODULE: Record<string, string> = {
  roles: "ROLES_PERMISOS",
  usuarios: "USUARIOS",
  "cat-insumos": "CATEGORIAS_INSUMOS",
  insumos: "INSUMOS",
  proveedores: "PROVEEDORES",
  compras: "COMPRAS",
  perdidas: "PERDIDA_INSUMOS",
  "cat-producto": "CATEGORIAS_PRODUCTO",
  producto: "PRODUCTOS",
  produccion: "ORDENES_PRODUCCION",
  "producto-no-conforme": "PRODUCTO_NO_CONFORME",
  clientes: "CLIENTES",
  pedidos: "PEDIDOS",
  domicilios: "BARRIOS",
  ventas: "VENTAS",
  devoluciones: "DEVOLUCIONES",
}
// What each panel section's records are called (titles, dialogs)
const PURCHASE_ENTITIES: Record<string, { name: string; fem: boolean }> = {
  "cat-insumos": { name: "categoría de insumo", fem: true },
  insumos: { name: "insumo", fem: false },
  proveedores: { name: "proveedor", fem: false },
  compras: { name: "compra", fem: true },
  perdidas: { name: "pérdida de insumo", fem: true },
  "cat-producto": { name: "categoría de producto", fem: true },
  produccion: { name: "orden de producción", fem: true },
  "producto-no-conforme": { name: "producto no conforme", fem: false },
  clientes: { name: "cliente", fem: false },
  pedidos: { name: "pedido", fem: false },
  domicilios: { name: "domicilio", fem: false },
  ventas: { name: "venta", fem: true },
  devoluciones: { name: "devolución", fem: true },
}
const PERM_MODULE: Record<string, string> = {
  "Roles y permisos": "ROLES_PERMISOS",
  Usuarios: "USUARIOS",
  "Categoría Insumos": "CATEGORIAS_INSUMOS",
  Insumos: "INSUMOS",
  Proveedores: "PROVEEDORES",
  Compras: "COMPRAS",
  "Pérdida Insumos": "PERDIDA_INSUMOS",
  "Categoría Producto": "CATEGORIAS_PRODUCTO",
  Productos: "PRODUCTOS",
  Producción: "ORDENES_PRODUCCION",
  "Producto No Conforme": "PRODUCTO_NO_CONFORME",
  Clientes: "CLIENTES",
  Pedidos: "PEDIDOS",
  Domicilios: "BARRIOS",
  Ventas: "VENTAS",
  Devoluciones: "DEVOLUCIONES",
}
// The backend has one privilege for both "Anular" and "Eliminar" (each module shows one of them)
const PERM_ACTION: Record<string, string> = { Ver: "VER", Crear: "CREAR", Editar: "EDITAR", Anular: "ELIMINAR", Eliminar: "ELIMINAR" }
type RolePerms = Record<string, string[]>
const permsToDb = (perms: RolePerms) =>
  PERMISSION_MODULES.map(({ name }) => ({
    modulo: PERM_MODULE[name],
    privilegios: [...new Set((perms[name] || []).map((a) => PERM_ACTION[a]).filter(Boolean))].sort(),
  })).filter((p) => p.privilegios.length)
const permsFromDb = (permisos: { modulo: string; privilegios: string[] }[]): RolePerms =>
  Object.fromEntries(
    PERMISSION_MODULES.map(({ name, finalAction }) => [
      name,
      (permisos.find((p) => p.modulo === PERM_MODULE[name])?.privilegios || []).map((p) =>
        p === "ELIMINAR" ? finalAction : p[0] + p.slice(1).toLowerCase(),
      ),
    ]),
  )

// ── Panel modules stored as whole rows ─────────────────────────────────────────
// Their logic lives in the panel (status history, order lines, stock already used...), so the
// backend stores each row as-is (plus its main columns). AdminPanel saves any change automatically.
type PanelSyncSpec = {
  path: string
  // Position of the backend id in the row (right after the panel's own cells; never shown)
  idIndex: number
  // Rows built in the browser before loading that must still be saved (default: none)
  keepLocal?: (row: Row, dbRows: Row[]) => boolean
  // Rows this module saves (default: all); the others are kept as they are and never sent
  owns?: (row: Row) => boolean
}
const PANEL_SYNC: Record<string, PanelSyncSpec> = {
  // Production orders rebuilt from client orders (not the demo seed) are saved if the backend doesn't have them
  produccion: {
    path: "/ordenes-produccion",
    idIndex: 17,
    keepLocal: (row, dbRows) =>
      !dbRows.some((r) => r[0] === row[0] || (!!row[15] && r[15] === row[15] && String(r[8]) !== "Producto no conforme")) &&
      !MOD_CFG.produccion.seed.some((r) => r[0] === row[0]),
  },
  "producto-no-conforme": { path: "/productos-no-conformes", idIndex: 9 },
  ventas: { path: "/ventas", idIndex: 13 },
  // 6 = returned products (JSON); older records have none
  devoluciones: { path: "/devoluciones", idIndex: 7 },
  // Orders created by hand in the panel; web store orders are saved through /pedidos
  pedidos: {
    path: "/pedidos-panel",
    // 12 is the comment; older records have no comment and get it empty
    idIndex: 13,
    owns: (row) => !loadOrders().some((order) => order.id === row[0]),
  },
}
// Short filter next to "Buscar": the specific columns (row index) each module can be filtered by
const TABLE_FILTERS: Record<string, { label: string; index: number }[]> = {
  roles: [{ label: "Estado", index: 2 }],
  usuarios: [{ label: "Rol", index: 3 }, { label: "Estado", index: 5 }],
  "cat-insumos": [{ label: "Estado", index: 2 }],
  insumos: [{ label: "Categoría", index: 1 }, { label: "Estado", index: 12 }],
  proveedores: [{ label: "Tipo de persona", index: 15 }, { label: "Estado", index: 6 }],
  compras: [{ label: "Proveedor", index: 0 }, { label: "Estado", index: 5 }],
  perdidas: [{ label: "Motivo", index: 2 }],
  "cat-producto": [{ label: "Estado", index: 2 }],
  producto: [{ label: "Categoría", index: 1 }, { label: "Estado", index: 4 }],
  // produccion: day and status have their own controls (see GenericTable)
  "producto-no-conforme": [{ label: "Estado", index: 8 }],
  clientes: [{ label: "Estado", index: 7 }],
  domicilios: [{ label: "Zona cercana", index: 1 }, { label: "Estado", index: 4 }],
  ventas: [{ label: "Método de pago", index: 5 }, { label: "Estado del pedido", index: 10 }],
  pedidos: [
    { label: "Estado", index: 7 },
    { label: "Estado de pago", index: 8 },
    { label: "Tipo de pedido", index: 3 },
  ],
  devoluciones: [{ label: "Motivo", index: 4 }],
}
const syncIdIndex = (sec: string) => (DB_SYNC[sec] ?? PANEL_SYNC[sec])?.idIndex
// Sales made when an order was paid used to be saved one column off: [4 productos, 5 tipo, 6 método, 7-8 total,
// 9 "Pendiente", 10 pedido, 11 estado, 12 productos JSON]. Read them in the usual columns (only on screen;
// the backend keeps them as they are, so loading them doesn't save anything)
const fixShiftedSale = (row: Row): Row => {
  if (String(row[9]) !== "Pendiente" || !/^PED-/i.test(String(row[10] ?? ""))) return row
  const fixed = [...row]
  for (let i = 4; i <= 11; i++) fixed[i] = row[i + 1]
  fixed[8] = ""
  fixed[12] = ""
  return fixed
}
// Pads the row so the id never leaves empty gaps before it
const withPanelId = (row: Row, idIndex: number, id: string | number) => {
  const padded = Array.from({ length: Math.max(row.length, idIndex) }, (_, i) => row[i] ?? "")
  padded[idIndex] = id
  return padded
}

// Backend categories that feed the customization options instead of the menu
const EXTRA_CATS = ["Adiciones", "Salsas", "Bebidas", "Sabores de bebida"]

// shortcut: replaces the menu arrays in place so every screen reading them shows the backend data;
// move them into state/context when the admin panel edits them live.
async function loadMenu() {
  const items = await api<CatalogItem[]>("/catalogo")
  const activeItems = items
    .map((item) => ({ ...item, categoria: currentCategory(item.categoria) }))
    .filter(
      (item) => !["INACTIVO", "INACTIVA", "ANULADO", "ANULADA"].includes(String(item.estado ?? "").trim().toUpperCase()),
    )
  const inCat = (cat: string) => activeItems.filter((p) => p.categoria === cat)
  ADDITIONS.splice(0, ADDITIONS.length, ...inCat("Adiciones").map((p) => ({ name: p.nombre, price: p.precio })))
  SAUCES.splice(0, SAUCES.length, ...inCat("Salsas").map((p) => p.nombre))
  const rank = (f: string) => (BEVERAGE_ORDER.indexOf(f) + 1 || 99)
  // Each soda is a product of «Bebidas» named "Gaseosa <sabor> (<tamaño>)": flavours, sizes, prices and photos come from them
  // (other drinks there, without that name, aren't offered as sodas)
  const sodaProducts = inCat("Bebidas").flatMap((p) => {
    const m = SODA_RE.exec(p.nombre.trim())
    return m ? [{ name: p.nombre, flavor: m[1], size: m[2], price: p.precio, img: p.imagenes[0] ? imageUrl(p.imagenes[0]) : "" }] : []
  })
  // Bought sodas with no stock left (an older backend without this route sells them all)
  const soldOut = new Set(
    (await api<{ nombre: string; agotada: boolean }[]>("/catalogo/gaseosas").catch(() => []))
      .filter((g) => g.agotada)
      .map((g) => normalizeName(g.nombre)),
  )
  SODA_INFO.clear()
  if (sodaProducts.length) {
    sodaProducts.forEach((s) =>
      SODA_INFO.set(normalizeName(`Gaseosa ${s.flavor} (${s.size})`), { precio: s.price, img: s.img, agotada: soldOut.has(normalizeName(s.name)) }),
    )
    BEVERAGES.splice(0, BEVERAGES.length, ...[...new Set(sodaProducts.map((s) => s.flavor))].sort((a, b) => rank(a) - rank(b)))
    // Size buttons from small to big, each showing its cheapest soda
    const sizes = [...new Set(sodaProducts.map((s) => s.size))].sort((a, b) => sizeMl(a) - sizeMl(b))
    BEVERAGE_SIZES.splice(
      0,
      BEVERAGE_SIZES.length,
      ...sizes.map((size) => ({ id: size, label: size, price: Math.min(...sodaProducts.filter((s) => s.size === size).map((s) => s.price)) })),
    )
  } else {
    // No sodas for sale: the Bebidas tab says so
    BEVERAGES.splice(0, BEVERAGES.length)
  }
  MENU_EXTRAS.splice(
    0,
    MENU_EXTRAS.length,
    ...activeItems
      .filter((item) => ["Adiciones", "Salsas", "Bebidas"].includes(item.categoria))
      .map((item) => {
        const soda = item.categoria === "Bebidas" ? SODA_RE.exec(item.nombre.trim()) : null
        return {
          id: item.id,
          name: item.nombre,
          desc: item.descripcion || "",
          price: item.precio,
          priceStr: fmt(item.precio),
          img: imageUrl(item.imagenes[0]) || (soda ? beverageImage(soda[1], soda[2]) || "" : ""),
          cat: normalizeName(item.categoria).replace(/\s+/g, "-"),
          badge: item.etiqueta || "",
          soldOut: !!soda && soldOut.has(normalizeName(item.nombre)),
        }
      }),
  )
  PRODUCTS.splice(
    0,
    PRODUCTS.length,
    ...activeItems.filter((p) => !EXTRA_CATS.includes(p.categoria)).map((p) => {
      const fallbackProduct =
        PRODUCTS.find((product) => product.id === p.id) ??
        PRODUCTS.find((product) => normalizeName(product.name) === normalizeName(p.nombre))
      const isTraditionalBurger = normalizeName(p.nombre) === normalizeName("Tradicional")
      return {
        id: p.id,
        name: p.nombre,
        desc: p.descripcion || "",
        price: p.precio,
        priceStr: fmt(p.precio),
        img: isTraditionalBurger
          ? traditionalBurgerImg
          : imageUrl(p.imagenes[0]) || fallbackProduct?.img || "",
        cat: MENU_CAT_ID[currentCategory(p.categoria)] || p.categoria.toLowerCase(),
        badge: p.etiqueta || "",
      }
    }),
  )
}

const refreshCartProducts = (items: CartItem[]) => {
  const products = allMenuProducts()
  return items.flatMap((item) => {
    const product =
      products.find((candidate) => candidate.id === item.productId) ??
      products.find((candidate) => candidate.name === item.name) ??
      products.find((candidate) => candidate.name === `Hamburguesa ${item.name}`)
    if (!product) return []
    return [{
      ...item,
      productId: product.id,
      name: product.name,
      description: product.desc,
      price: product.price,
      img: product.img,
      additions: item.additions?.map((addition) => {
        const currentAddition = ADDITIONS.find((candidate) => candidate.name === addition.name)
        return currentAddition ? { ...addition, price: currentAddition.price } : addition
      }),
    }]
  })
}

